const state={me:null,csrf:null,route:'dashboard',data:{},sidebar:false};
const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const AI_BROWSER_KEY='nute-ris-v60-ai-browser-settings';
const AI_BROWSER_LEGACY_KEYS=['nute-ris-v542-ai-browser-settings'];
function getAISettings(){try{let raw=sessionStorage.getItem(AI_BROWSER_KEY);if(!raw){for(const k of AI_BROWSER_LEGACY_KEYS){raw=sessionStorage.getItem(k);if(raw){sessionStorage.setItem(AI_BROWSER_KEY,raw);break}}}return JSON.parse(raw||'null')||{mode:'demo',provider:'openai',model:'',apiKey:'',baseUrl:''}}catch{return{mode:'demo',provider:'openai',model:'',apiKey:'',baseUrl:''}}}
function saveAISettings(x){sessionStorage.setItem(AI_BROWSER_KEY,JSON.stringify(x))}
function clearAISettings(){sessionStorage.removeItem(AI_BROWSER_KEY);for(const k of AI_BROWSER_LEGACY_KEYS)sessionStorage.removeItem(k)}
function aiBrowserEnabled(){const x=getAISettings();return x.mode==='byok'&&!!x.model&&(x.provider==='ollama'||!!x.apiKey)}
function decodeTextFile(f){try{if(!f?.base64)return'';if(!/^(text\/|application\/(json|xml))/i.test(f.type||'')&&!/\.(txt|md|csv|json|xml|html?)$/i.test(f.name||''))return'';const bin=atob(f.base64);const bytes=Uint8Array.from(bin,c=>c.charCodeAt(0));return new TextDecoder('utf-8').decode(bytes)}catch{return''}}
function buildAIPrompt(data={}){const texts=(data.files||[]).map(f=>{const t=decodeTextFile(f);return t?`\n--- TỆP: ${f.name} ---\n${t.slice(0,30000)}`:`\n--- TỆP: ${f.name} (${f.type||'unknown'}) ---\n[Tệp nhị phân được đính kèm nếu provider hỗ trợ.]`}).join('');return `Bạn là AI Research Partner của NUTE Research Intelligence System. Hỗ trợ phân tích nghiên cứu, không bịa nguồn hoặc dữ liệu; nêu rõ giới hạn; quyết định nghiệp vụ và khoa học cuối cùng thuộc con người.\n\nNHIỆM VỤ: ${data.task||'Phân tích nghiên cứu'}\n\nNỘI DUNG:\n${data.content||'(không có văn bản nhập trực tiếp)'}${texts}`}
function aiResultText(x){
  if(typeof x==='string')return x;
  if(!x||typeof x!=='object')return '';
  if(typeof x.output_text==='string'&&x.output_text)return x.output_text;
  const responseText=(x.output||[]).flatMap(o=>o?.content||[]).map(c=>c?.text||c?.output_text||'').filter(Boolean).join('');
  if(responseText)return responseText;
  const choice=x?.choices?.[0]?.message?.content;
  if(typeof choice==='string')return choice;
  if(Array.isArray(choice)){const t=choice.map(c=>typeof c==='string'?c:(c?.text||c?.content||'')).filter(Boolean).join('');if(t)return t}
  const gemini=(x?.candidates?.[0]?.content?.parts||[]).map(p=>p?.text||'').filter(Boolean).join('');
  if(gemini)return gemini;
  const anthropic=(Array.isArray(x?.content)?x.content:[]).map(p=>p?.text||'').filter(Boolean).join('');
  if(anthropic)return anthropic;
  return x?.message?.content||x?.response||'';
}

async function realAIInfer(data={}){const cfg=await requireRealAI();const prompt=buildAIPrompt(data);const provider=cfg.provider;let url='',headers={'Content-Type':'application/json'},body={};
  if(provider==='openai'){
    url=(cfg.baseUrl||'https://api.openai.com/v1').replace(/\/$/,'')+'/responses';headers.Authorization='Bearer '+cfg.apiKey;
    const content=[{type:'input_text',text:prompt}];for(const f of (data.files||[])){if(!f.base64)continue;if(f.type==='application/pdf')content.push({type:'input_file',filename:f.name||'document.pdf',file_data:`data:${f.type};base64,${f.base64}`});else if(/^image\//i.test(f.type||''))content.push({type:'input_image',image_url:`data:${f.type};base64,${f.base64}`})}
    body={model:cfg.model,input:[{role:'user',content}]};
  }else if(provider==='gemini'){
    url=(cfg.baseUrl||'https://generativelanguage.googleapis.com/v1beta').replace(/\/$/,'')+`/models/${encodeURIComponent(cfg.model)}:generateContent?key=${encodeURIComponent(cfg.apiKey)}`;
    const parts=[{text:prompt}];for(const f of (data.files||[])){if(f.base64&&f.type)parts.push({inlineData:{mimeType:f.type,data:f.base64}})}body={contents:[{role:'user',parts}]};
  }else if(provider==='anthropic'){
    url=(cfg.baseUrl||'https://api.anthropic.com/v1').replace(/\/$/,'')+'/messages';headers['x-api-key']=cfg.apiKey;headers['anthropic-version']='2023-06-01';headers['anthropic-dangerous-direct-browser-access']='true';
    const content=[{type:'text',text:prompt}];for(const f of (data.files||[])){if(!f.base64)continue;if(f.type==='application/pdf')content.push({type:'document',source:{type:'base64',media_type:'application/pdf',data:f.base64}});else if(/^image\//i.test(f.type||''))content.push({type:'image',source:{type:'base64',media_type:f.type,data:f.base64}})}body={model:cfg.model,max_tokens:1800,messages:[{role:'user',content}]};
  }else if(provider==='openrouter'){
    url=(cfg.baseUrl||'https://openrouter.ai/api/v1').replace(/\/$/,'')+'/chat/completions';headers.Authorization='Bearer '+cfg.apiKey;headers['HTTP-Referer']=location.origin;headers['X-Title']='NUTE Research GitHub Test';{const media=(data.files||[]).filter(f=>f.base64&&/^image\//i.test(f.type||''));const c=media.length?[{type:'text',text:prompt},...media.map(f=>({type:'image_url',image_url:{url:`data:${f.type};base64,${f.base64}`}}))]:prompt;body={model:cfg.model,messages:[{role:'user',content:c}]};}
  }else if(provider==='groq'||provider==='custom'){
    const base=(cfg.baseUrl||(provider==='groq'?'https://api.groq.com/openai/v1':'')).replace(/\/$/,'');if(!base)throw new Error('Provider custom cần API Endpoint.');url=/\/chat\/completions$/i.test(base)?base:base+'/chat/completions';headers.Authorization='Bearer '+cfg.apiKey;{const media=(data.files||[]).filter(f=>f.base64&&/^image\//i.test(f.type||''));const c=media.length?[{type:'text',text:prompt},...media.map(f=>({type:'image_url',image_url:{url:`data:${f.type};base64,${f.base64}`}}))]:prompt;body={model:cfg.model,messages:[{role:'user',content:c}]};}
  }else if(provider==='ollama'){
    const base=(cfg.baseUrl||'http://localhost:11434').replace(/\/$/,'');url=base+'/api/chat';body={model:cfg.model,messages:[{role:'user',content:prompt}],stream:false};
  }else throw new Error('Provider chưa được hỗ trợ trong chế độ Browser BYOK.');
  let res;try{res=await fetch(url,{method:'POST',headers,body:JSON.stringify(body)})}catch(e){throw new Error('Trình duyệt không gọi được provider (có thể do CORS/network): '+e.message)}
  let json={};try{json=await res.json()}catch{}if(!res.ok)throw new Error(json?.error?.message||json?.message||`AI provider trả HTTP ${res.status}`);const text=aiResultText(json);if(!text)throw new Error('Provider đã phản hồi nhưng không đọc được nội dung trả về.');return {result:text,provider:{name:provider,model:cfg.model},raw:json};
}

const AI_REGISTRY_SECRET_KEY='nute-ris-v602-ai-registry-secrets';
function registrySecrets(){try{return JSON.parse(sessionStorage.getItem(AI_REGISTRY_SECRET_KEY)||'{}')||{}}catch{return{}}}
function saveRegistrySecret(id,key){if(!id||!key)return;const x=registrySecrets();x[id]=key;sessionStorage.setItem(AI_REGISTRY_SECRET_KEY,JSON.stringify(x))}

function isLegacyDemoProvider(p={}){const n=String(p.name||'').toLowerCase(),m=String(p.model||'').toLowerCase();return n.includes('demo')||m==='gpt-demo'||m==='gemini-demo'||m.endsWith('-demo')}
async function syncAISettingsFromRegistry(preferredId=''){
  let list=[];try{list=await window.demoApi('/api/ai/providers')}catch{return null}
  const secrets=registrySecrets();
  const candidates=(list||[]).filter(p=>p&&p.enabled!==false&&p.model&&!isLegacyDemoProvider(p)&&(String(p.kind||'').toLowerCase()==='ollama'||!!secrets[p.id]));
  candidates.sort((a,b)=>{if(preferredId){if(a.id===preferredId)return-1;if(b.id===preferredId)return 1}if(!!a.primary!==!!b.primary)return a.primary?-1:1;return Number(a.priority||100)-Number(b.priority||100)});
  const p=candidates[0];if(!p)return null;
  const cfg={mode:'byok',provider:String(p.kind||'').toLowerCase(),model:p.model,apiKey:secrets[p.id]||'',baseUrl:p.endpoint||'',registryId:p.id,registryName:p.name||p.id};
  saveAISettings(cfg);return cfg;
}
async function resolveAISettings(){let cfg=getAISettings();if(cfg.mode==='byok'&&cfg.model&&(cfg.provider==='ollama'||cfg.apiKey))return cfg;return (await syncAISettingsFromRegistry(cfg.registryId||''))||cfg}
async function requireRealAI(){const cfg=await resolveAISettings();if(!(cfg.mode==='byok'&&cfg.model&&(cfg.provider==='ollama'||cfg.apiKey)))throw new Error('Chưa có provider AI thật đang hoạt động. Vào AI Model Registry, nhập API key thật, chọn model, kiểm tra kết nối và Lưu Registry.');return cfg}
async function disableLegacyDemoProviders(){let list=[];try{list=await window.demoApi('/api/ai/providers')}catch{return}for(const p of list||[]){if(isLegacyDemoProvider(p)&&(p.enabled!==false||p.primary)){try{await window.demoApi('/api/ai/providers',{method:'POST',body:JSON.stringify({...p,enabled:false,primary:false,active:false,apiKey:''})})}catch{}}}}
async function registryConfig(data={}){
  let saved=null;
  if(data.id){try{const list=await window.demoApi('/api/ai/providers');saved=list.find(x=>x.id===data.id)||null}catch{}}
  const cfg={...(saved||{}),...data};
  if(!cfg.apiKey&&cfg.id)cfg.apiKey=registrySecrets()[cfg.id]||'';
  cfg.kind=String(cfg.kind||'').toLowerCase();
  return cfg;
}
function registryBase(cfg){
  const e=String(cfg.endpoint||'').replace(/\/$/,'');
  if(e)return e;
  return ({openai:'https://api.openai.com/v1',gemini:'https://generativelanguage.googleapis.com/v1beta',anthropic:'https://api.anthropic.com/v1',openrouter:'https://openrouter.ai/api/v1',groq:'https://api.groq.com/openai/v1',ollama:'http://localhost:11434',custom:''})[cfg.kind]||'';
}
function registryHeaders(cfg){
  const h={'Content-Type':'application/json'};
  if(['openai','openrouter','groq','custom'].includes(cfg.kind)&&cfg.apiKey)h.Authorization='Bearer '+cfg.apiKey;
  if(cfg.kind==='anthropic'){h['x-api-key']=cfg.apiKey||'';h['anthropic-version']='2023-06-01';h['anthropic-dangerous-direct-browser-access']='true'}
  if(cfg.kind==='openrouter'){h['HTTP-Referer']=location.origin;h['X-Title']='NUTE Research GitHub Test'}
  return h;
}
function registryNeedKey(cfg){return !['ollama'].includes(cfg.kind)&&!cfg.apiKey}
async function registryFetchJson(url,opts={}){
  let r;try{r=await fetch(url,opts)}catch(e){throw new Error('Không gọi được provider từ trình duyệt (network/CORS): '+e.message)}
  let j={};try{j=await r.json()}catch{}
  if(!r.ok)throw new Error(j?.error?.message||j?.message||j?.detail||`Provider trả HTTP ${r.status}`);
  return j;
}
function filterGenerationModels(models=[]){
  const bad=/(embedding|moderation|audio|whisper|tts|realtime|image|dall-e|babbage|davinci-002|rerank|transcri)/i;
  return models.filter(m=>m?.id&&!bad.test(m.id)).map(m=>({id:m.id,name:m.name||m.displayName||m.id,raw:m}));
}
async function registryModels(data={}){
  const cfg=await registryConfig(data);if(registryNeedKey(cfg))throw new Error('Chưa có API key trong phiên này. Hãy nhập lại API key để lấy danh sách model thật.');
  const base=registryBase(cfg);let url=String(cfg.modelsEndpoint||'').trim(),j;
  if(!url){
    if(cfg.kind==='gemini')url=`${base}/models?key=${encodeURIComponent(cfg.apiKey)}`;
    else if(cfg.kind==='ollama')url=`${base}/api/tags`;
    else url=`${base}/models`;
  }
  j=await registryFetchJson(url,{headers:registryHeaders(cfg)});
  let raw=[];
  if(cfg.kind==='gemini')raw=(j.models||[]).filter(m=>(m.supportedGenerationMethods||[]).includes('generateContent')).map(m=>({id:String(m.name||'').replace(/^models\//,''),name:m.displayName||m.name}));
  else if(cfg.kind==='ollama')raw=(j.models||[]).map(m=>({id:m.name||m.model,name:m.name||m.model}));
  else raw=(j.data||j.models||[]).map(m=>({id:m.id||m.name||m.model,name:m.name||m.display_name||m.id||m.model}));
  const models=filterGenerationModels(raw);return {count:models.length,models};
}
async function registryTest(data={}){
  const cfg=await registryConfig(data);if(registryNeedKey(cfg))throw new Error('Chưa có API key trong phiên này. Hãy mở Cấu hình và nhập lại key trước khi kiểm tra.');
  if(!cfg.model)throw new Error('Chưa chọn Model ID.');
  const base=registryBase(cfg),prompt='Trả lời đúng một câu ngắn: Kết nối AI thật thành công.';let url='',body={},headers=registryHeaders(cfg);
  if(cfg.kind==='openai') {url=base.endsWith('/responses')?base:base+'/responses';body={model:cfg.model,input:prompt}}
  else if(cfg.kind==='gemini'){url=base+`/models/${encodeURIComponent(cfg.model)}:generateContent?key=${encodeURIComponent(cfg.apiKey)}`;body={contents:[{role:'user',parts:[{text:prompt}]}]}}
  else if(cfg.kind==='anthropic'){url=base.endsWith('/messages')?base:base+'/messages';body={model:cfg.model,max_tokens:80,messages:[{role:'user',content:prompt}]}}
  else if(['openrouter','groq','custom'].includes(cfg.kind)){url=/\/chat\/completions$/i.test(base)?base:base+'/chat/completions';body={model:cfg.model,messages:[{role:'user',content:prompt}],max_tokens:80}}
  else if(cfg.kind==='ollama'){url=base+'/api/chat';body={model:cfg.model,messages:[{role:'user',content:prompt}],stream:false}}
  else throw new Error('Provider chưa được hỗ trợ để kiểm tra thật trên GitHub Pages.');
  const j=await registryFetchJson(url,{method:'POST',headers,body:JSON.stringify(body)});let text=aiResultText(j);
  if(cfg.kind==='ollama')text=j?.message?.content||j?.response||text;
  if(!text)throw new Error('Provider phản hồi nhưng RIS không đọc được nội dung.');
  return {model:cfg.model,response:text,provider:cfg.kind,real:true};
}
async function registryProbe(data={}){
  const cfg=await registryConfig(data);const t=await registryTest(cfg);const id=String(cfg.model||'').toLowerCase();
  const capabilities={chat:true,temperature:!/(^o1|^o3|^o4)/.test(id),vision:/(vision|gpt-4o|gpt-5|gemini|claude-3|claude-sonnet|claude-opus)/.test(id),jsonMode:['openai','openrouter','groq','gemini'].includes(cfg.kind),reasoning:/(reason|^o1|^o3|^o4|gpt-5|gemini.*pro|claude)/.test(id),toolCalling:['openai','openrouter','groq','gemini','anthropic'].includes(cfg.kind),streaming:true,embeddings:false};
  return {reachable:true,capabilities,probes:{base:{ok:true,response:t.response}},model:cfg.model,provider:cfg.kind,real:true};
}
function compactAIContext(x,depth=0){if(depth>5)return '[MAX_DEPTH]';if(Array.isArray(x))return x.slice(0,30).map(v=>compactAIContext(v,depth+1));if(x&&typeof x==='object'){const o={};for(const [k,v] of Object.entries(x)){if(k==='base64')o[k]='[BINARY_OMITTED]';else if(typeof v==='string'&&v.length>12000)o[k]=v.slice(0,12000)+'...[TRUNCATED]';else o[k]=compactAIContext(v,depth+1)}return o}return x}
async function emitAIActivityFromApi(url,method,opts,response){
  if(!window.NuteAIActivity||method!=='POST'||url.startsWith('/api/ai/'))return;
  let request={};try{request=JSON.parse(opts.body||'{}')}catch{}
  let activity='',researchId='',entityType='RESEARCH',entityId='';
  let m;
  if(url==='/api/research'){activity='RESEARCH_CREATED';researchId=response?.id||'';entityId=researchId}
  else if((m=url.match(/^\/api\/research\/([^/]+)\/transition$/))){activity='WORKFLOW_TRANSITION';researchId=m[1];entityId=researchId}
  else if((m=url.match(/^\/api\/research\/([^/]+)\/evidence$/))){activity='EVIDENCE_SUBMITTED';researchId=m[1];entityId=researchId}
  else if((m=url.match(/^\/api\/research\/([^/]+)\/documents$/))){activity='DOCUMENT_UPLOADED';researchId=m[1];entityId=researchId}
  else if((m=url.match(/^\/api\/evidence\/([^/]+)\/verify$/))){activity='EVIDENCE_VERIFIED';researchId=response?.researchId||'';entityType='EVIDENCE';entityId=m[1]}
  else if((m=url.match(/^\/api\/research\/([^/]+)\/council$/))){activity='COUNCIL_RESULT';researchId=m[1];entityId=researchId}
  else if((m=url.match(/^\/api\/research\/([^/]+)\/recognize$/))){activity='RECOGNITION';researchId=m[1];entityId=researchId}
  if(!activity)return;
  let research=null;try{if(researchId)research=await window.demoApi(`/api/research/${researchId}`)}catch{}
  await syncAISettingsFromRegistry().catch(()=>null);
  window.NuteAIActivity.configure({infer:null});
  const legacy=await window.NuteAIActivity.observe({activity,researchId,entityType,entityId,context:compactAIContext({request,response,research})});
  emitAgenticActivityFromApi(activity,researchId,entityType,entityId,{request,response,research});
  return legacy;
}
async function api(url,opts={}){
  const method=(opts.method||'GET').toUpperCase();
  if(method==='POST'&&url==='/api/ai/providers/models'){let data={};try{data=JSON.parse(opts.body||'{}')}catch{}return registryModels(data)}
  if(method==='POST'&&url==='/api/ai/providers/probe'){let data={};try{data=JSON.parse(opts.body||'{}')}catch{}return registryProbe(data)}
  if(method==='POST'&&url==='/api/ai/providers/test'){let data={};try{data=JSON.parse(opts.body||'{}')}catch{}return registryTest(data)}
  if(method==='POST'&&url==='/api/ai/assist'){let data={};try{data=JSON.parse(opts.body||'{}')}catch{}await syncAISettingsFromRegistry().catch(()=>null);return realAIInfer(data)}
  if(method==='POST'&&url==='/api/ai/portfolio/analyze'){await syncAISettingsFromRegistry().catch(()=>null);const rs=await window.demoApi('/api/research');return realAIInfer({task:'Phân tích danh mục nghiên cứu toàn hệ thống, chỉ ra điểm nghẽn, trùng lặp chủ đề, khoảng trống và ưu tiên quản trị.',content:JSON.stringify(rs.map(r=>({title:r.title,status:r.status,type:r.type?.name,organization:r.organization?.name,summary:r.summary})),null,2)})}
  let mm;
  if(method==='POST'&&(mm=url.match(/^\/api\/research\/([^/]+)\/transition-advice$/))){await syncAISettingsFromRegistry().catch(()=>null);const r=await window.demoApi(`/api/research/${mm[1]}`);let data={};try{data=JSON.parse(opts.body||'{}')}catch{}const x=await realAIInfer({task:`Phân tích hồ sơ trước quyết định chuyển trạng thái sang ${data.to||''}. Nêu điều kiện còn thiếu, rủi ro, căn cứ cần kiểm tra và khuyến nghị; không tự quyết định thay người có thẩm quyền.`,content:JSON.stringify(compactAIContext(r),null,2)});return {id:'real-ai-'+Date.now(),result:x.result,providerName:x.provider.name,model:x.provider.model,real:true}}
  if(method==='POST'&&(mm=url.match(/^\/api\/workflows\/([^/]+)\/analyze$/))){await syncAISettingsFromRegistry().catch(()=>null);const list=await window.demoApi('/api/workflows');const w=list.find(x=>x.id===mm[1]);const x=await realAIInfer({task:'Phân tích toàn bộ cấu hình workflow và tài liệu nguồn: phát hiện bước thiếu, xung đột quyền, minh chứng bắt buộc, decision gate và rủi ro quản trị.',content:JSON.stringify(compactAIContext(w),null,2)});return {result:x.result,provider:x.provider,real:true}}
  if(method==='POST'&&(mm=url.match(/^\/api\/knowledge\/([^/]+)\/analyze$/))){await syncAISettingsFromRegistry().catch(()=>null);const list=await window.demoApi('/api/knowledge');const k=list.find(x=>x.id===mm[1]);const x=await realAIInfer({task:'Phân tích quy chế/tri thức. Trích xuất yêu cầu, thẩm quyền, điều kiện, minh chứng và xung đột; không bịa điều khoản không có trong nội dung.',content:JSON.stringify(compactAIContext(k),null,2)});await window.demoApi(url,{method:'POST',body:JSON.stringify({real:true})}).catch(()=>null);return {result:x.result,provider:x.provider,real:true}}
  if(method==='POST'&&(mm=url.match(/^\/api\/ai\/work-items\/([^/]+)\/process$/))){await syncAISettingsFromRegistry().catch(()=>null);const dc=await window.demoApi('/api/ai/decision-center');const wi=(dc.workItems||[]).find(x=>x.id===mm[1]);const x=await realAIInfer({task:`Phân tích decision point ${wi?.decisionPoint||''}. Trả khuyến nghị có căn cứ, rủi ro và các điểm cần người có thẩm quyền xác minh.`,content:JSON.stringify(compactAIContext(wi),null,2)});opts={...opts,body:JSON.stringify({aiResult:x.result,provider:x.provider})}}
  const response=await window.demoApi(url,opts);
  if(method==='POST'&&url==='/api/ai/providers'){let data={};try{data=JSON.parse(opts.body||'{}')}catch{}if(data.apiKey&&response?.id)saveRegistrySecret(response.id,data.apiKey);await syncAISettingsFromRegistry(response?.id||'').catch(()=>null)}
  try{await emitAIActivityFromApi(url,method,opts,response)}catch(e){console.warn('[RIS V6 AI Activity]',e)}
  return response;
}
function showError(e){alert(e?.message||String(e))}
async function filePayload(file){if(!file||!file.size)return null;if(file.size>25*1024*1024)throw new Error('Tệp vượt quá 25 MB.');return await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>{const raw=String(r.result||'');resolve({name:file.name,type:file.type||'',size:file.size,base64:raw.includes(',')?raw.split(',')[1]:raw})};r.onerror=()=>reject(new Error('Không đọc được tệp.'));r.readAsDataURL(file)})}
async function filesPayload(files){const list=[...(files||[])];if(list.length>10)throw new Error('Mỗi lần chỉ chọn tối đa 10 tệp.');return Promise.all(list.map(filePayload))}
function setupMultiFileInput(inputId,listId){const input=$(inputId),box=$(listId);const selected=[];const render=()=>{if(!box)return;box.innerHTML=selected.length?selected.map((f,i)=>`<span class="file-chip"><span>${esc(f.name)} <small>${Math.ceil(f.size/1024)} KB</small></span><button type="button" data-remove-file="${i}">×</button></span>`).join(''):'<span class="note">Chưa chọn tệp.</span>';box.querySelectorAll('[data-remove-file]').forEach(b=>b.onclick=()=>{selected.splice(Number(b.dataset.removeFile),1);render()})};if(input){input.onchange=()=>{for(const f of [...input.files]){if(!selected.some(x=>x.name===f.name&&x.size===f.size))selected.push(f)}input.value='';render()}}render();return {files:()=>selected,clear:()=>{selected.length=0;render()}}}
async function agentToolInvoker(toolId,args={},meta={}){
  if(toolId==='research.list')return api('/api/research');
  if(toolId==='research.get')return api(`/api/research/${encodeURIComponent(args.id||'')}`);
  if(toolId==='workflow.inspect')return api('/api/workflows');
  if(toolId==='knowledge.list')return api('/api/knowledge');
  if(toolId==='personnel.list')return api('/api/personnel');
  if(toolId==='organization.list')return api('/api/organizations');
  if(toolId==='audit.list')return api('/api/audit');
  if(toolId==='intelligence.portfolio')return api('/api/intelligence/portfolio');
  if(toolId==='intelligence.search')return api('/api/intelligence/search?q='+encodeURIComponent(args.q||''));
  if(toolId==='research.create_draft')return {prepared:true,requiresHumanConfirmation:true,draft:args};
  if(toolId==='notification.prepare')return {prepared:true,requiresHumanConfirmation:true,notification:args};
  if(toolId==='decision.draft')return {prepared:true,requiresHumanConfirmation:true,decision:args};
  throw new Error('Tool chưa được nối vào RIS: '+toolId);
}
async function agentContextProvider(agentId,input={},base={}){
  const ctx={...base,route:state.route,currentEntity:state.currentEntity||input.entity||null,permissions:[...(state.permissions||[])],timestamp:new Date().toISOString()};
  try{
    if(ctx.currentEntity?.type==='RESEARCH'&&ctx.currentEntity.id)ctx.research=compactAIContext(await api(`/api/research/${ctx.currentEntity.id}`));
    if(['governance_compliance','research_copilot','data_intake','council_review'].includes(agentId))ctx.knowledge=compactAIContext(await api('/api/knowledge'));
    if(['executive_intelligence','portfolio_intelligence','workflow'].includes(agentId))ctx.portfolio=compactAIContext(await api('/api/intelligence/portfolio'));
  }catch(e){ctx.contextWarning=e.message}
  return ctx;
}
async function configureAgenticRuntime(){
  if(!window.NuteAgenticRIS)return;
  await syncAISettingsFromRegistry().catch(()=>null);
  window.NuteAgenticRIS.configure({
    infer:async d=>{await syncAISettingsFromRegistry().catch(()=>null);return realAIInfer(d)},
    invokeTool:agentToolInvoker,
    contextProvider:agentContextProvider,
    currentUser:()=>state.me?{id:state.me.id,displayName:state.me.displayName,roles:state.me.roles,organizationId:state.me.organizationId}:null
  });
  startAgentMonitoring();
}
let agentMonitoringTimer=null;
function startAgentMonitoring(){if(agentMonitoringTimer)clearInterval(agentMonitoringTimer);if(!window.NuteAgenticRIS)return;agentMonitoringTimer=setInterval(()=>{const st=window.NuteAgenticRIS.summary();if(!st.settings?.continuousMonitoring||!aiBrowserEnabled()||!state.me)return;window.NuteAgenticRIS.run({agentId:'workflow',trigger:'ON_SCHEDULE',message:'Rà soát các hồ sơ đang hoạt động, phát hiện deadline, hồ sơ bị tắc và việc cần xử lý.'}).catch(()=>null);if(has('intelligence.read'))window.NuteAgenticRIS.run({agentId:'portfolio_intelligence',trigger:'ON_SCHEDULE',message:'Rà soát danh mục nghiên cứu, phát hiện xu hướng, rủi ro và cơ hội mới cần chú ý.'}).catch(()=>null)},30*60*1000)}
function agentForActivity(activity){return ({RESEARCH_CREATED:'data_intake',WORKFLOW_TRANSITION:'workflow',EVIDENCE_SUBMITTED:'evidence_document',DOCUMENT_UPLOADED:'evidence_document',EVIDENCE_VERIFIED:'governance_compliance',COUNCIL_RESULT:'council_review',RECOGNITION:'governance_compliance'})[activity]||'research_copilot'}
function emitAgenticActivityFromApi(activity,researchId,entityType,entityId,context={}){
  if(!window.NuteAgenticRIS||!activity)return;
  const agentId=agentForActivity(activity);const labels={RESEARCH_CREATED:'Phân tích hồ sơ nghiên cứu vừa được tạo và chỉ ra dữ liệu còn thiếu.',WORKFLOW_TRANSITION:'Hậu kiểm bước chuyển workflow vừa xảy ra; phát hiện rủi ro và việc cần theo dõi.',EVIDENCE_SUBMITTED:'Đánh giá minh chứng mới được nộp, mức độ phù hợp và thiếu sót.',DOCUMENT_UPLOADED:'Phân tích tài liệu mới và ánh xạ vào hồ sơ nghiên cứu.',EVIDENCE_VERIFIED:'Hậu kiểm kết quả xác minh minh chứng và các tác động compliance.',COUNCIL_RESULT:'Tổng hợp kết quả hội đồng, điểm bất thường và hành động tiếp theo.',RECOGNITION:'Hậu kiểm quyết định công nhận và các nghĩa vụ sau công nhận.'};
  window.NuteAgenticRIS.run({agentId,trigger:'ON_EVENT',message:labels[activity]||activity,entity:researchId?{type:'RESEARCH',id:researchId}:{type:entityType,id:entityId},context:compactAIContext(context)}).catch(e=>console.warn('[RIS V7 Agent Event]',e));
}
function agentTaskHtml(t){const r=t?.result||{};return `<div class="agent-result"><div class="split"><b>${esc(r.agentName||t.agentId||'Agent')}</b><span class="pill ${t.status==='COMPLETED'?'ok':t.status==='FAILED'?'danger':''}">${esc(t.status||'')}</span></div>${r.summary?`<p>${esc(r.summary)}</p>`:''}${r.recommendations?.length?`<div class="note"><b>Khuyến nghị:</b> ${r.recommendations.slice(0,3).map(esc).join(' · ')}</div>`:''}${r.risks?.length?`<div class="note"><b>Rủi ro:</b> ${r.risks.slice(0,3).map(esc).join(' · ')}</div>`:''}<small>${fmt(t.completedAt||t.createdAt)}${t.provider?.name?` · ${esc(t.provider.name)} / ${esc(t.provider.model||'')}`:''}</small></div>`}
function mountAgentDock(){
  if(!window.NuteAgenticRIS||document.querySelector('#agentDock'))return;
  const box=document.createElement('div');box.id='agentDock';box.className='agent-dock';box.innerHTML=`<button class="agent-fab" id="agentFab" title="RIS AI Agents">✦</button><div class="agent-panel" id="agentPanel"><div class="agent-panel-head"><div><b>RIS AI Agent Supervisor</b><small>V7.0 · Context-aware · Multimodal</small></div><button class="btn sm" id="agentClose">×</button></div><div class="field"><span>Agent</span><select id="agentSelect"><option value="">Tự động chọn agent</option>${window.NuteAgenticRIS.agents().filter(a=>a.enabled!==false).map(a=>`<option value="${esc(a.id)}">${esc(a.name)}</option>`).join('')}</select></div><div id="agentAttachments" class="file-stack"><span class="note">Có thể đính kèm tài liệu, ảnh, audio hoặc video.</span></div><textarea id="agentMessage" placeholder="Ví dụ: Phân tích hồ sơ hiện tại; tạo draft từ tài liệu; lập kịch bản chiến lược..."></textarea><input id="agentFiles" type="file" multiple hidden accept=".pdf,.doc,.docx,.txt,.md,.csv,.json,image/*,audio/*,video/*"><input id="agentCamera" type="file" hidden accept="image/*" capture="environment"><input id="agentVideo" type="file" hidden accept="video/*" capture="environment"><div class="agent-toolbar"><button class="btn sm" id="agentMic">🎤 Nói</button><button class="btn sm" id="agentRecord">🎙 Ghi âm</button><button class="btn sm" id="agentAttach">📎 Tệp</button><button class="btn sm" id="agentCameraBtn">📷 Camera</button><button class="btn sm" id="agentVideoBtn">🎥 Video</button><button class="btn sm" id="agentSpeak">🔊 Đọc</button></div><button class="btn primary" id="agentRun">Giao việc cho Agent Supervisor</button><div id="agentOutput" class="agent-output"><div class="empty">Agent sẽ tự chọn chuyên gia phù hợp và có thể phối hợp nhiều agent.</div></div><div class="actions"><button class="btn sm" id="agentCenterBtn">Mở Agent Center</button></div></div>`;document.body.appendChild(box);
  const files=[];const renderFiles=()=>{$('#agentAttachments').innerHTML=files.length?files.map((f,i)=>`<span class="file-chip">${esc(f.name)} <button type="button" data-af="${i}">×</button></span>`).join(''):'<span class="note">Có thể đính kèm tài liệu, ảnh, audio hoặc video.</span>';document.querySelectorAll('[data-af]').forEach(b=>b.onclick=()=>{files.splice(Number(b.dataset.af),1);renderFiles()})};
  $('#agentFab').onclick=()=>$('#agentPanel').classList.toggle('open');$('#agentClose').onclick=()=>$('#agentPanel').classList.remove('open');$('#agentAttach').onclick=()=>$('#agentFiles').click();$('#agentCameraBtn').onclick=()=>$('#agentCamera').click();$('#agentVideoBtn').onclick=()=>$('#agentVideo').click();$('#agentFiles').onchange=e=>{files.push(...e.target.files);e.target.value='';renderFiles()};$('#agentCamera').onchange=e=>{files.push(...e.target.files);e.target.value='';renderFiles()};$('#agentVideo').onchange=e=>{files.push(...e.target.files);e.target.value='';renderFiles()};
  let lastSpeech='';$('#agentRun').onclick=async()=>{const msg=$('#agentMessage').value.trim();if(!msg&&!files.length)return showError(new Error('Hãy nhập yêu cầu hoặc đính kèm tệp.'));const b=$('#agentRun');try{b.disabled=true;b.textContent='Agents đang xử lý...';const payloads=await filesPayload(files);const task=await window.NuteAgenticRIS.runTeam({agentId:$('#agentSelect').value||undefined,message:msg||'Phân tích các tệp đính kèm.',files:payloads,route:state.route,entity:state.currentEntity||null});lastSpeech=task.result?.summary||'';$('#agentOutput').innerHTML=agentTaskHtml(task)}catch(e){$('#agentOutput').innerHTML=`<div class="error">${esc(e.message)}</div>`}finally{b.disabled=false;b.textContent='Giao việc cho Agent Supervisor'}};
  $('#agentCenterBtn').onclick=()=>{go('agents');$('#agentPanel').classList.remove('open')};$('#agentSpeak').onclick=()=>{if(!lastSpeech)return;if('speechSynthesis'in window){speechSynthesis.cancel();speechSynthesis.speak(new SpeechSynthesisUtterance(lastSpeech))}};
  $('#agentMic').onclick=()=>{const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR)return showError(new Error('Trình duyệt chưa hỗ trợ SpeechRecognition. Có thể dùng nút Tệp để tải audio.'));const r=new SR();r.lang='vi-VN';r.interimResults=false;r.onresult=e=>{$('#agentMessage').value=String(e.results?.[0]?.[0]?.transcript||'')};r.onerror=e=>showError(new Error('Không nhận dạng được giọng nói: '+e.error));r.start()};
  let recorder=null,recordChunks=[],recordStream=null;$('#agentRecord').onclick=async()=>{const b=$('#agentRecord');if(recorder&&recorder.state==='recording'){recorder.stop();return}try{if(!navigator.mediaDevices?.getUserMedia)throw new Error('Trình duyệt không hỗ trợ ghi âm.');recordStream=await navigator.mediaDevices.getUserMedia({audio:true});recordChunks=[];recorder=new MediaRecorder(recordStream);recorder.ondataavailable=e=>{if(e.data?.size)recordChunks.push(e.data)};recorder.onstop=()=>{const type=recorder.mimeType||'audio/webm';const blob=new Blob(recordChunks,{type});files.push(new File([blob],`ris-recording-${Date.now()}.webm`,{type}));renderFiles();recordStream?.getTracks().forEach(t=>t.stop());recordStream=null;b.textContent='🎙 Ghi âm'};recorder.start();b.textContent='■ Dừng ghi'}catch(e){showError(e)}};
}
async function agentCenterPage(){
  if(!window.NuteAgenticRIS){$('#view').innerHTML='<div class="error">Agent Runtime chưa được nạp.</div>';return}const s=window.NuteAgenticRIS.summary();$('#view').innerHTML=`<div class="page-head"><div><h2>AI Agent Center · V7.0</h2><p>Agent Registry, Task Monitor, Tool Governance và Decision Memory.</p></div><button class="btn" id="openDock">Mở Agent Supervisor</button></div><div class="grid cards"><div class="card metric"><div class="label">Agents</div><div class="num">${s.agents.length}</div></div><div class="card metric"><div class="label">Tasks</div><div class="num">${s.tasks.length}</div></div><div class="card metric"><div class="label">Decision Memory</div><div class="num">${s.decisionMemory.length}</div></div><div class="card metric"><div class="label">Tools</div><div class="num">${s.toolRegistry.length}</div></div></div><div class="grid" style="margin-top:18px">${s.agents.map(a=>`<div class="card agent-card"><div class="split"><div><h3>${esc(a.name)}</h3><small>${esc(a.id)} · ${esc(a.defaultAutonomy)}</small></div><label class="switch"><input type="checkbox" data-agent-toggle="${esc(a.id)}" ${a.enabled!==false?'checked':''}><span></span></label></div><p>${esc(a.description)}</p><div class="agent-tags">${(a.modalities||[]).map(x=>`<span class="pill">${esc(x)}</span>`).join('')}</div><small>Capabilities: ${esc((a.capabilities||[]).join(', '))}</small></div>`).join('')}</div><div class="card" style="margin-top:18px"><div class="split"><h3>Agent Tasks gần đây</h3><span class="note">Mọi task đều audit được.</span></div>${s.tasks.slice(0,12).map(agentTaskHtml).join('')||'<div class="empty">Chưa có task.</div>'}</div><div class="card" style="margin-top:18px"><h3>Tool Registry</h3><div class="table-wrap"><table class="table"><thead><tr><th>Tool</th><th>Risk</th><th>Agents được phép</th></tr></thead><tbody>${s.toolRegistry.map(t=>`<tr><td class="code">${esc(t.id)}</td><td>${esc(t.risk)}</td><td>${esc(t.agents.join(', '))}</td></tr>`).join('')}</tbody></table></div></div>`;$('#openDock').onclick=()=>$('#agentPanel')?.classList.add('open');document.querySelectorAll('[data-agent-toggle]').forEach(x=>x.onchange=()=>{window.NuteAgenticRIS.setAgentEnabled(x.dataset.agentToggle,x.checked);agentCenterPage()})
}
async function executivePage(){
  const [p,rs,orgs]=await Promise.all([api('/api/intelligence/portfolio'),api('/api/research'),api('/api/organizations')]);const recognized=rs.filter(r=>r.status==='RECOGNIZED').length;const active=rs.filter(r=>!['RECOGNIZED','REJECTED'].includes(r.status)).length;const s=window.NuteAgenticRIS?.summary?.()||{decisionMemory:[],tasks:[]};$('#view').innerHTML=`<div class="page-head"><div><h2>Executive Intelligence</h2><p>Strategic Decision Intelligence cho Ban giám hiệu: dữ liệu, kịch bản, rủi ro, định hướng và Decision Memory.</p></div><span class="pill ok">Human Decision Authority</span></div><div class="grid cards"><div class="card metric"><div class="label">Danh mục nghiên cứu</div><div class="num">${rs.length}</div></div><div class="card metric"><div class="label">Đang hoạt động</div><div class="num">${active}</div></div><div class="card metric"><div class="label">Đã công nhận</div><div class="num">${recognized}</div></div><div class="card metric"><div class="label">Đơn vị</div><div class="num">${orgs.length}</div></div></div><div class="grid" style="margin-top:18px"><div class="card"><h3>Strategic Health</h3><p>Hồ sơ chậm: <b>${p.stale?.length||0}</b> · Pending AI: <b>${p.pendingAI||0}</b></p><div class="agent-tags">${Object.entries(p.byStatus||{}).map(([k,v])=>`<span class="pill">${esc(k)}: ${v}</span>`).join('')}</div></div><div class="card"><h3>Executive Decision Intelligence</h3><div class="field"><span>Câu hỏi / kịch bản</span><textarea id="execQuestion" placeholder="Ví dụ: Nếu ưu tiên 20% nguồn lực cho AI và tự động hóa trong 3 năm tới, nên có những kịch bản nào và rủi ro gì?"></textarea></div><button class="btn primary" id="execAnalyze">Phân tích chiến lược</button><div id="execResult"></div></div></div><div class="card" style="margin-top:18px"><h3>Decision Memory</h3>${s.decisionMemory.slice(0,10).map(d=>`<div class="note-item"><b>${esc(d.question||'Quyết định')}</b><p>${esc(d.rationale||d.outcome||'')}</p><small>${fmt(d.createdAt)} · ${esc(d.outcome)}</small></div>`).join('')||'<div class="empty">Chưa có quyết định được ghi vào Decision Memory.</div>'}</div>`;$('#execAnalyze').onclick=async()=>{const q=$('#execQuestion').value.trim();if(!q)return showError(new Error('Hãy nhập câu hỏi chiến lược.'));const b=$('#execAnalyze');try{b.disabled=true;b.textContent='Executive Agents đang phân tích...';const t=await window.NuteAgenticRIS.runTeam({agentId:'executive_intelligence',message:q,context:{portfolio:p,researchCount:rs.length,organizations:orgs.map(o=>({id:o.id,name:o.name}))}});$('#execResult').innerHTML=agentTaskHtml(t)+`<div class="actions"><button class="btn sm" id="execAccept">Ghi nhận vào Decision Memory</button></div>`;$('#execAccept').onclick=()=>{const rationale=prompt('Căn cứ/quyết định của lãnh đạo:','')||'';window.NuteAgenticRIS.recordDecision(t.id,{outcome:'ACCEPTED_FOR_CONSIDERATION',rationale,actorId:state.me.id});executivePage()}}catch(e){$('#execResult').innerHTML=`<div class="error">${esc(e.message)}</div>`}finally{b.disabled=false;b.textContent='Phân tích chiến lược'}}
}

async function boot(){try{await disableLegacyDemoProviders();await syncAISettingsFromRegistry().catch(()=>null);const st=await api('/api/bootstrap/status');if(!st.initialized)return renderBootstrap();try{const me=await api('/api/me');state.me=me.user;state.csrf=me.csrf;state.permissions=new Set(me.permissions||[]);await configureAgenticRuntime();renderShell();go('dashboard')}catch{renderLogin()}}catch(e){document.querySelector('#app').innerHTML=`<div class="center"><div class="auth"><div class="error">${esc(e.message)}</div></div></div>`}}
function renderBootstrap(){$('#app').innerHTML=`<div class="center"><form class="auth" id="bootstrap"><div class="logo"><img src="./logo-nute.jpg"><div><h1>Khởi tạo NUTE Research</h1><p>Thiết lập quản trị viên đầu tiên. Dữ liệu nghiệp vụ ban đầu để trống.</p></div></div><div class="field"><span>Họ tên quản trị viên</span><input name="displayName" required></div><div class="field"><span>Tài khoản</span><input name="username" autocomplete="username" required></div><div class="field"><span>Mật khẩu (tối thiểu 10 ký tự)</span><input name="password" type="password" autocomplete="new-password" required minlength="10"></div><button class="btn primary" style="width:100%">Khởi tạo hệ thống</button><p class="note">Khóa mã hóa cục bộ sẽ tự sinh nếu biến môi trường <span class="code">NUTE_MASTER_ENCRYPTION_KEY</span> chưa được cấu hình. Khi triển khai thật nên đặt biến môi trường này bên ngoài repository.</p></form></div>`;$('#bootstrap').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await api('/api/bootstrap',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});renderLogin('Khởi tạo thành công. Hãy đăng nhập.')}catch(x){showError(x)}}}
function renderLogin(msg=''){document.querySelector('#agentDock')?.remove();$('#app').innerHTML=`<div class="center"><form class="auth" id="login"><div class="logo"><img src="./logo-nute.jpg"><div><h1>NUTE Research</h1><p>Quản lý hoạt động nghiên cứu khoa học & AI</p></div></div>${msg?`<div class="success">${esc(msg)}</div>`:''}<div class="field"><span>Tài khoản</span><input name="username" autocomplete="username" required autofocus></div><div class="field"><span>Mật khẩu</span><input name="password" type="password" autocomplete="current-password" required></div><button class="btn primary" style="width:100%">Đăng nhập</button></form></div>`;$('#login').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));try{const r=await api('/api/auth/login',{method:'POST',body:JSON.stringify(f)});state.me=r.user;state.csrf=r.csrf;const me=await api('/api/me');state.permissions=new Set(me.permissions||[]);await configureAgenticRuntime();renderShell();go('dashboard')}catch(x){showError(x)}}}
function has(p){return state.permissions?.has('*')||state.permissions?.has(p)}
function renderShell(){const admin=has('user.manage')||has('config.manage')||has('ai.configure');const initials=String(state.me.displayName||'NUTE').split(/\s+/).slice(-2).map(x=>x[0]||'').join('').toUpperCase();$('#app').innerHTML=`<div class="shell"><aside class="sidebar" id="sidebar"><div class="brand"><img src="./logo-nute.jpg"><div><strong>NUTE Research</strong><small>Agentic RIS · V7.0 · Multi-Agent Intelligence</small></div></div><nav class="nav"><button data-route="dashboard">Tổng quan</button><div class="section">Nghiên cứu</div><button data-route="research">Hồ sơ nghiên cứu</button>${(has('academic.ai.use')||has('ai.use'))?'<button data-route="workspace">AI Research Workspace</button>':''}${has('intelligence.read')?'<button data-route="intelligence">Research Intelligence</button><button data-route="executive">Executive Intelligence</button>':''}${has('ai.decision.read')?'<button data-route="ai-decisions">AI Decision Center</button>':''}${has('ai.use')?'<button data-route="ai">AI Research Copilot</button><button data-route="ai-settings">AI Settings</button><button data-route="agents">AI Agent Center</button>':''}<button data-route="profile">Hồ sơ năng lực nghiên cứu</button><button data-route="scientific-profile">Hồ sơ khoa học</button>${admin?'<div class="section">Quản trị hệ thống</div>':''}${has('user.manage')?'<button data-route="personnel">Danh sách cán bộ / GV / SV</button><button data-route="users">Tài khoản</button>':''}${has('role.manage')?'<button data-route="roles">Vai trò & quyền</button>':''}${has('organization.manage')?'<button data-route="organizations">Đơn vị</button>':''}${has('config.manage')?'<button data-route="types">Loại nghiên cứu</button><button data-route="workflows">Quy trình</button>':''}${has('knowledge.manage')?'<button data-route="knowledge">Kho tri thức & Quy chế</button><button data-route="form-studio">AI Form Studio</button>':''}<button data-route="forms">Biểu mẫu điện tử</button><button data-route="signature-settings">Chữ ký & chứng thư số</button>${has('ai.configure')?'<button data-route="providers">AI Model Registry</button>':''}${has('audit.read')?'<button data-route="audit">Nhật ký hệ thống</button>':''}</nav></aside><main class="main"><header class="topbar"><div class="topbar-left"><button class="btn mobile-toggle" id="toggle">☰</button><span class="ai-chip"><i></i> AGENTIC AI WORKSPACE</span></div><div class="who"><div class="avatar">${esc(initials)}</div><div class="who-copy"><strong>${esc(state.me.displayName)}</strong><small>${esc(state.me.roles.join(', '))}</small></div><button class="btn sm" id="logout">Đăng xuất</button></div></header><section class="content" id="view"></section></main></div>`;mountAgentDock();document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>go(b.dataset.route));$('#logout').onclick=async()=>{try{await api('/api/auth/logout',{method:'POST'});state.me=null;state.csrf=null;if(agentMonitoringTimer){clearInterval(agentMonitoringTimer);agentMonitoringTimer=null}document.querySelector('#agentDock')?.remove();renderLogin()}catch(e){showError(e)}};$('#toggle').onclick=()=>$('#sidebar').classList.toggle('open')}
async function go(route){state.route=route;state.currentEntity=null;document.querySelectorAll('[data-route]').forEach(b=>b.classList.toggle('active',b.dataset.route===route));$('#sidebar')?.classList.remove('open');const v=$('#view');v.innerHTML='<div class="muted">Đang tải...</div>';try{if(route==='dashboard')return dashboard();if(route==='research')return research();if(route==='workspace')return researchWorkspaceList();if(route==='intelligence')return intelligence();if(route==='executive')return executivePage();if(route==='profile')return profilePage();if(route==='scientific-profile')return scientificProfilePage();if(route==='knowledge')return knowledgePage();if(route==='form-studio')return formStudioPage();if(route==='forms')return formsPage();if(route==='signature-settings')return signatureSettingsPage();if(route==='ai-decisions')return aiDecisionCenter();if(route==='ai')return ai();if(route==='ai-settings')return aiSettings();if(route==='agents')return agentCenterPage();if(route==='personnel')return personnelPage();if(route==='users')return users();if(route==='roles')return roles();if(route==='organizations')return organizations();if(route==='types')return types();if(route==='workflows')return workflows();if(route==='providers')return providers();if(route==='audit')return auditView()}catch(e){v.innerHTML=`<div class="error">${esc(e.message)}</div>`}}
async function dashboard(){const d=await api('/api/dashboard');const flows=d.flows||[];$('#view').innerHTML=`<div class="page-head"><div><h2>Tổng quan nghiên cứu</h2><p>Research Intelligence System: AI hỗ trợ xuyên suốt vòng đời; con người quyết định tại các cấp phê duyệt.</p></div></div>${has('ai.use')?`<div class="ai-hero"><div class="hero-inner"><div><div class="kicker">NUTE AGENTIC RESEARCH INTELLIGENCE</div><h3>Researcher + Institutional + Executive Intelligence</h3><p>AI đồng hành với người nghiên cứu và hỗ trợ từng cấp xét duyệt; mọi quyết định cuối cùng do con người có thẩm quyền thực hiện.</p></div><button class="btn" id="openAIHero">Mở AI Agent Center →</button></div></div>`:''}<div class="grid cards"><div class="card metric"><div class="trend-dot"></div><div class="label">Tổng hồ sơ</div><div class="num">${d.counts.total}</div></div><div class="card metric"><div class="trend-dot"></div><div class="label">Đang thực hiện</div><div class="num">${d.counts.active}</div></div><div class="card metric"><div class="trend-dot"></div><div class="label">Cần xử lý</div><div class="num">${d.counts.needsAction}</div></div><div class="card metric"><div class="trend-dot"></div><div class="label">Đã công nhận</div><div class="num">${d.counts.recognized}</div></div></div><div class="card" style="margin-top:18px"><div class="split"><div><h3 style="margin:0 0 4px">Luồng hồ sơ đang chạy</h3><span class="note">Mỗi người nhìn thấy vị trí hiện tại, bước tiếp theo và lịch sử quyết định của hồ sơ mình được phép truy cập.</span></div></div><div class="flow-board">${flows.length?flows.map(f=>`<div class="flow-card"><div class="split"><div><b>${esc(f.title)}</b><small>${esc(f.type||'')} · ${esc(f.organization||'')}</small></div><span class="pill">${esc(f.status)}</span></div><div class="flow-next">${f.next?.length?f.next.map(n=>`<span class="flow-step ${n.allowed?'ready':'waiting'}">${esc(n.from)} → ${esc(n.to)}${n.aiAssist?' · AI+Human':''}</span>`).join(''):'<span class="note">Không có bước tiếp theo được cấu hình.</span>'}</div>${f.decisions?.length?`<div class="note">Quyết định gần nhất: ${esc(f.decisions[0].from)} → ${esc(f.decisions[0].to)} · ${fmt(f.decisions[0].createdAt)}</div>`:''}<button class="btn sm" data-open-flow="${esc(f.id)}">Mở hồ sơ</button></div>`).join(''):'<div class="empty">Chưa có hồ sơ trong luồng.</div>'}</div></div><div class="card" style="margin-top:18px"><div class="split"><div><h3 style="margin:0 0 4px">Hồ sơ gần đây</h3><span class="note">Các hoạt động cần theo dõi gần nhất</span></div><button class="btn sm" id="toResearch">Xem tất cả</button></div><div style="margin-top:14px">${researchRows(d.recent)}</div></div><div class="footer-note">NUTE Research · Agentic AI-Native · SBBS Capability-First Architecture</div>`;$('#toResearch').onclick=()=>go('research');if($('#openAIHero'))$('#openAIHero').onclick=()=>go('agents');document.querySelectorAll('[data-open-flow]').forEach(b=>b.onclick=()=>openResearch(b.dataset.openFlow))}
function researchRows(list){if(!list?.length)return '<div class="empty">Chưa có hồ sơ nghiên cứu.</div>';return `<div class="table-wrap"><table class="table"><thead><tr><th>Hoạt động</th><th>Đơn vị</th><th>Loại</th><th>Trạng thái</th><th>Cập nhật</th><th></th></tr></thead><tbody>${list.map(r=>`<tr><td><strong>${esc(r.title)}</strong></td><td>${esc(r.organization?.name||'Chưa gán')}</td><td>${esc(r.type?.name||'Chưa cấu hình')}</td><td><span class="pill">${esc(r.status)}</span></td><td>${fmt(r.updatedAt)}</td><td><button class="btn sm" data-open="${esc(r.id)}">Mở</button></td></tr>`).join('')}</tbody></table></div>`}
async function research(){const [list,types,orgs]=await Promise.all([api('/api/research'),api('/api/research-types'),api('/api/organizations')]);state.data.research=list;state.data.types=types;state.data.organizations=orgs;$('#view').innerHTML=`<div class="page-head"><div><h2>Hồ sơ nghiên cứu</h2><p>Đề tài, công bố, sáng kiến, sở hữu trí tuệ và các hoạt động khác được quản lý theo loại hình và đơn vị.</p></div>${has('research.create')?'<button class="btn primary" id="newResearch">+ Tạo hồ sơ</button>':''}</div>${researchRows(list)}`;document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openResearch(b.dataset.open));if($('#newResearch'))$('#newResearch').onclick=()=>researchModal(types,orgs)}
function researchModal(types,orgs){const defaultOrg=state.me?.organizationId||'';modal(`<h3>Tạo hồ sơ / đăng ký hoạt động nghiên cứu</h3><form id="rf"><div class="row"><div class="field"><span>Loại hoạt động</span><select name="typeId" required><option value="">-- Chọn --</option>${types.map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('')}</select></div><div class="field"><span>Đơn vị quản lý / thực hiện</span><select name="organizationId" required><option value="">-- Chọn đơn vị --</option>${orgs.filter(o=>o.active!==false).map(o=>`<option value="${esc(o.id)}" ${o.id===defaultOrg?'selected':''}>${esc(o.name)}</option>`).join('')}</select></div></div><div class="field"><span>Tên hoạt động / công trình</span><input name="title" required></div><div class="field"><span>Mô tả tóm tắt</span><textarea name="summary"></textarea></div><div class="field"><span>Hồ sơ đăng ký — có thể chọn nhiều tệp</span><input id="registrationFiles" type="file" multiple accept=".pdf,.doc,.docx,.txt,.md,.rtf"><div id="registrationFilesList" class="file-stack"></div><small class="field-help">Có thể chọn thêm nhiều lần và xóa từng tệp trước khi gửi. AI đọc văn bản trích xuất từ toàn bộ hồ sơ.</small></div><div class="actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn primary">Tạo hồ sơ đăng ký</button></div></form>`);const picker=setupMultiFileInput('#registrationFiles','#registrationFilesList');$('#rf').onsubmit=async e=>{e.preventDefault();try{const f=Object.fromEntries(new FormData(e.target));delete f.registrationFiles;f.registrationFiles=await filesPayload(picker.files());await api('/api/research',{method:'POST',body:JSON.stringify(f)});closeModal();research()}catch(x){showError(x)}}}

async function openResearch(id){
  state.currentEntity={type:'RESEARCH',id};
  const r=await api(`/api/research/${id}`);const next=r.availableTransitions||[];
  const v7=window.NuteAgenticRIS?.summary?.()||{tasks:[]};const aiRecent=(v7.tasks||[]).filter(x=>x.entity?.type==='RESEARCH'&&x.entity?.id===id&&x.status==='COMPLETED').slice(0,4);
  $('#view').innerHTML=`<div class="page-head"><div><button class="btn sm" id="back">← Hồ sơ</button><h2 style="margin-top:12px">${esc(r.title)}</h2><p>${esc(r.type?.name||'Chưa phân loại')} · ${esc(r.organization?.name||'Chưa gán đơn vị')} · <span class="pill">${esc(r.status)}</span></p></div></div><div class="detail"><div class="grid"><div class="card"><h3>Thông tin</h3><p>${esc(r.summary||'Chưa có mô tả.')}</p><div class="note">Đơn vị: <b>${esc(r.organization?.name||'Chưa gán')}</b> · Chủ hồ sơ: ${esc(r.owner?.displayName)} · Tạo: ${fmt(r.createdAt)}</div></div><div class="card"><div class="split"><div><h3>Agentic Continuous Monitoring · V7.0</h3><p class="note">AI tự phân tích các sự kiện có ý nghĩa của hồ sơ theo AI Activity Policy.</p></div><span class="pill ${aiBrowserEnabled()?'ok':''}">${aiBrowserEnabled()?'BYOK CONFIGURED':'FALLBACK'}</span></div>${aiRecent.length?aiRecent.map(x=>{const r=x.result||{};return `<div class="note-item"><div class="split"><b>${esc(r.agentName||x.agentId)}</b><span class="pill">${esc(r.status||'OK')}</span></div><p>${esc(r.summary||'Agent đã phân tích sự kiện.')}</p><small>${fmt(x.completedAt||x.createdAt)} · confidence ${Math.round(Number(r.confidence||0)*100)}%</small></div>`}).join(''):'<div class="empty">Chưa có Agent Task cho hồ sơ này. V7.0 sẽ tự phân tích khi phát sinh sự kiện hoặc khi bạn giao việc cho Agent Supervisor.</div>'}</div><div class="card"><div class="split"><div><h3>Tài liệu hồ sơ</h3><p class="note">PDF/DOC/DOCX được trích xuất để AI đọc trong ngữ cảnh hồ sơ.</p></div>${has('research.document.upload')?'<button class="btn sm" id="addResearchDoc">+ Tải tài liệu</button>':''}</div>${researchDocumentList(r.documents||[])}</div><div class="card"><div class="split"><h3>Minh chứng</h3>${has('evidence.upload')?'<button class="btn sm" id="addEvidence">+ Thêm</button>':''}</div>${evidenceList(r.evidence)}</div><div class="card"><div class="split"><h3>Kết quả hội đồng</h3>${has('council.manage')?'<button class="btn sm" id="addCouncil">+ Ghi kết quả</button>':''}</div>${(r.councils||[]).length?`<div class="timeline">${r.councils.map(c=>`<div class="item"><strong>${esc(c.result)}</strong>${c.score!=null?` · Điểm ${esc(c.score)}`:''}<div class="note">Ngày họp: ${esc(c.meetingDate)}${c.minutes?` · ${esc(c.minutes)}`:''}</div></div>`).join('')}</div>`:'<div class="empty">Chưa có kết quả hội đồng.</div>'}</div></div><div class="grid"><div class="card"><h3>Thao tác theo vai trò · Human + AI</h3><p class="note">AI phân tích hồ sơ và đưa khuyến nghị tại điểm quyết định. Người có thẩm quyền luôn là người quyết định cuối cùng và ghi căn cứ.</p>${next.length?next.map((t,i)=>`<div class="workflow-action ${t.allowed?'':'locked'}"><div><b>${esc(transitionLabel(t.to))}</b><small>${t.permission?'Quyền: '+esc(t.permission):'Theo quyền chủ trì/thành viên'}${t.actionType?` · ${esc(t.actionType)}`:''}${t.reason?' · '+esc(t.reason):''}</small>${t.aiAssist?'<span class="human-ai-badge">AI hỗ trợ · Human quyết định</span>':''}</div><button class="btn ${t.allowed?'primary':''} sm" data-transition-index="${i}" ${t.allowed?'':'disabled'}>${esc(transitionVerb(t.to))}</button></div>`).join(''):'<div class="muted">Không có bước chuyển tiếp được cấu hình.</div>'}<div class="decision-history">${(r.workflowDecisions||[]).filter(x=>x.kind==='HUMAN_DECISION').slice(0,6).map(x=>`<div class="note-item"><b>${esc(x.from)} → ${esc(x.to)}</b><p>${esc(x.rationale||'Không ghi chú')}</p><small>${fmt(x.createdAt)}</small></div>`).join('')}</div>${has('recognition.approve')&&!r.recognitions?.length?'<div style="margin-top:12px"><button class="btn" id="recognize">Ghi quyết định công nhận</button></div>':''}${r.recognitions?.length?`<div class="success" style="margin-top:12px">Đã công nhận · QĐ ${esc(r.recognitions[0].decisionNo||'chưa ghi số')} · ${esc(r.recognitions[0].decisionDate)}</div>`:''}</div>${has('ai.use')?`<div class="card"><h3>AI hỗ trợ hồ sơ</h3><div class="field"><span>Yêu cầu</span><select id="aitask"><option>Phân tích tính đầy đủ hồ sơ</option><option>Phát hiện điểm chưa nhất quán</option><option>Gợi ý cải thiện thuyết minh</option></select></div><button class="btn primary" id="aiAnalyze">Phân tích bằng AI</button></div>`:''}${has('intelligence.read')?`<div class="card"><h3>Research Intelligence</h3><p class="note">Tìm nghiên cứu tương tự, quy chế liên quan và chuyên gia phù hợp trên dữ liệu nội bộ.</p><div class="actions"><button class="btn sm" id="similarResearch">Nghiên cứu tương tự</button>${has('reviewer.match')?'<button class="btn sm" id="matchReviewer">Gợi ý phản biện</button>':''}<button class="btn sm" id="policyCheck">Quy chế liên quan</button></div><div id="intelDetail" style="margin-top:12px"></div></div>`:''}</div></div>`;
  $('#back').onclick=()=>research();
  document.querySelectorAll('[data-transition-index]').forEach(b=>b.onclick=()=>workflowDecisionModal(id,next[Number(b.dataset.transitionIndex)]));
  document.querySelectorAll('[data-verify]').forEach(b=>b.onclick=async()=>{const approved=b.dataset.ok==='1';const note=prompt(approved?'Ghi chú xác nhận (có thể để trống):':'Lý do từ chối:','')||'';try{await api(`/api/evidence/${b.dataset.verify}/verify`,{method:'POST',body:JSON.stringify({approved,note})});openResearch(id)}catch(e){showError(e)}});
  document.querySelectorAll('[data-delete-rdoc]').forEach(b=>b.onclick=async()=>{if(!confirm('Xóa tài liệu này?'))return;try{await api(`/api/research-documents/${b.dataset.deleteRdoc}`,{method:'DELETE'});openResearch(id)}catch(e){showError(e)}});
  document.querySelectorAll('[data-delete-evidence]').forEach(b=>b.onclick=async()=>{if(!confirm('Xóa minh chứng này?'))return;try{await api(`/api/evidence/${b.dataset.deleteEvidence}`,{method:'DELETE'});openResearch(id)}catch(e){showError(e)}});
  if($('#addResearchDoc'))$('#addResearchDoc').onclick=()=>researchDocumentModal(id);if($('#addEvidence'))$('#addEvidence').onclick=()=>evidenceModal(id);if($('#addCouncil'))$('#addCouncil').onclick=()=>councilModal(id);if($('#recognize'))$('#recognize').onclick=()=>recognizeModal(id);
  if($('#aiAnalyze'))$('#aiAnalyze').onclick=async()=>{const out=document.createElement('div');out.className='ai-output';out.textContent='Đang phân tích...';$('#aiAnalyze').parentElement.append(out);try{const x=await api('/api/ai/assist',{method:'POST',body:JSON.stringify({route:'general',task:$('#aitask').value,content:`Tên: ${r.title}
Mô tả: ${r.summary}
Trạng thái: ${r.status}`,context:{researchId:r.id,type:r.type?.name,organization:r.organization?.name}})});out.textContent=`${x.result}

[AI: ${x.provider?.name||''} / ${x.provider?.model||''}]`}catch(e){out.textContent=e.message}};
  if($('#similarResearch'))$('#similarResearch').onclick=async()=>{const x=await api(`/api/intelligence/research/${id}/similar`);$('#intelDetail').innerHTML=x.length?x.map(v=>`<div class="intel-row"><b>${esc(v.research.title)}</b><span>Độ tương đồng ${(v.score*100).toFixed(0)}%</span></div>`).join(''):'<div class="empty">Chưa phát hiện nghiên cứu tương tự đáng kể.</div>'};
  if($('#matchReviewer'))$('#matchReviewer').onclick=async()=>{const x=await api(`/api/intelligence/research/${id}/reviewers`);$('#intelDetail').innerHTML=x.length?x.map(v=>`<div class="intel-row"><b>${esc(v.profile.displayName||v.profile.userId)}</b><span>${esc((v.profile.expertise||[]).join(', '))} · phù hợp ${(v.score*100).toFixed(0)}%</span></div>`).join(''):'<div class="empty">Chưa có hồ sơ chuyên gia đủ dữ liệu để ghép cặp.</div>'};
  if($('#policyCheck'))$('#policyCheck').onclick=async()=>{const x=await api(`/api/intelligence/research/${id}/policies`);$('#intelDetail').innerHTML=x.length?x.map(v=>`<div class="intel-row"><b>${esc(v.title)}</b><span>Liên quan ${(v.relevance*100).toFixed(0)}%</span></div>`).join(''):'<div class="empty">Chưa có quy chế/tri thức phù hợp trong kho.</div>'};
}
function workflowDecisionModal(rid,t){let adviceId='';modal(`<h3>${esc(transitionLabel(t.to))}</h3><p class="note">${t.aiAssist?'Điểm quyết định này được thiết kế theo Human + AI: AI hỗ trợ phân tích, con người chịu trách nhiệm quyết định.':'Thao tác này được thực hiện theo quyền của người dùng.'}</p>${t.aiAssist?`<div class="card inset"><div class="split"><b>AI Decision Support</b><button type="button" class="btn sm" id="getTransitionAdvice">AI phân tích trước quyết định</button></div><pre id="transitionAdvice" class="ai-doc-analysis">Chưa yêu cầu AI phân tích.</pre></div>`:''}<form id="transitionForm"><div class="field"><span>Căn cứ / lý do của người thực hiện ${t.decisionGate||['RETURN','REJECT'].includes(String(t.actionType||'').toUpperCase())?'(bắt buộc)':'(khuyến nghị)'}</span><textarea name="rationale" ${t.decisionGate||['RETURN','REJECT'].includes(String(t.actionType||'').toUpperCase())?'required':''} placeholder="Nêu căn cứ phê duyệt, trả lại hoặc chuyển bước..."></textarea></div><div class="actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn primary">${esc(transitionVerb(t.to))} · Human quyết định</button></div></form>`);if($('#getTransitionAdvice'))$('#getTransitionAdvice').onclick=async()=>{const b=$('#getTransitionAdvice'),box=$('#transitionAdvice');try{b.disabled=true;b.textContent='AI đang phân tích...';const x=await api(`/api/research/${rid}/transition-advice`,{method:'POST',body:JSON.stringify({to:t.to,note:$('#transitionForm textarea').value})});adviceId=x.id;box.textContent=`${x.result}

[AI: ${x.providerName} / ${x.model}]`}catch(e){box.textContent=e.message}finally{b.disabled=false;b.textContent='Phân tích lại bằng AI'}};$('#transitionForm').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(!confirm(`Xác nhận quyết định chuyển hồ sơ sang ${t.to}?`))return;try{await api(`/api/research/${rid}/transition`,{method:'POST',body:JSON.stringify({to:t.to,rationale:f.rationale,adviceId})});closeModal();openResearch(rid)}catch(x){showError(x)}}}
function transitionLabel(to){return ({SUBMITTED:'Gửi hồ sơ đăng ký',LEVEL2_APPROVED:'Đã duyệt cấp 2',LEVEL3_APPROVED:'Đã duyệt cấp 3',APPROVED:'Đã duyệt cấp 4 / phê duyệt cuối',IN_PROGRESS:'Bắt đầu thực hiện',RESULT_SUBMITTED:'Nộp kết quả thực hiện',COUNCIL_REVIEW:'Chuyển xem xét hội đồng',COMPLETED:'Xác nhận hoàn thành chuyên môn',RECOGNIZED:'Công nhận hoàn thành',REJECTED:'Từ chối hồ sơ',REVISION_REQUIRED:'Yêu cầu chỉnh sửa'})[to]||`Chuyển sang ${to}`}
function transitionVerb(to){return ({SUBMITTED:'Gửi đăng ký',LEVEL2_APPROVED:'Duyệt cấp 2',LEVEL3_APPROVED:'Duyệt cấp 3',APPROVED:'Duyệt cấp 4',IN_PROGRESS:'Bắt đầu',RESULT_SUBMITTED:'Nộp kết quả',COUNCIL_REVIEW:'Chuyển hội đồng',COMPLETED:'Hoàn thành',RECOGNIZED:'Công nhận',REJECTED:'Từ chối',REVISION_REQUIRED:'Yêu cầu sửa'})[to]||'Thực hiện'}
function approvalWorkflowTemplate(){return [
{from:'DRAFT',to:'SUBMITTED',permission:'research.submit',actionType:'SUBMIT',requiredEvidence:['REGISTRATION']},
{from:'SUBMITTED',to:'LEVEL2_APPROVED',permission:'research.approve.level2',actionType:'APPROVE_LEVEL_2',decisionGate:true,aiAssist:true},
{from:'SUBMITTED',to:'REVISION_REQUIRED',permission:'research.approve.level2',actionType:'RETURN_LEVEL_2',decisionGate:true,aiAssist:true},
{from:'REVISION_REQUIRED',to:'SUBMITTED',permission:'research.submit',actionType:'RESUBMIT',requiredEvidence:['REGISTRATION']},
{from:'LEVEL2_APPROVED',to:'LEVEL3_APPROVED',permission:'research.approve.level3',actionType:'APPROVE_LEVEL_3',decisionGate:true,aiAssist:true},
{from:'LEVEL2_APPROVED',to:'REVISION_REQUIRED',permission:'research.approve.level3',actionType:'RETURN_LEVEL_3',decisionGate:true,aiAssist:true},
{from:'LEVEL3_APPROVED',to:'APPROVED',permission:'research.approve.level4',actionType:'APPROVE_LEVEL_4',decisionGate:true,aiAssist:true},
{from:'LEVEL3_APPROVED',to:'REVISION_REQUIRED',permission:'research.approve.level4',actionType:'RETURN_LEVEL_4',decisionGate:true,aiAssist:true},
{from:'APPROVED',to:'IN_PROGRESS',permission:'research.submit',actionType:'START'},
{from:'IN_PROGRESS',to:'RESULT_SUBMITTED',permission:'research.submit',actionType:'SUBMIT_RESULT',requiredEvidence:['RESULT']},
{from:'RESULT_SUBMITTED',to:'COUNCIL_REVIEW',permission:'research.approve.level2',actionType:'SEND_COUNCIL',decisionGate:true,aiAssist:true},
{from:'COUNCIL_REVIEW',to:'COMPLETED',permission:'council.manage',actionType:'APPROVE_COUNCIL',decisionGate:true,aiAssist:true},
{from:'COUNCIL_REVIEW',to:'IN_PROGRESS',permission:'council.manage',actionType:'RETURN',decisionGate:true,aiAssist:true},
{from:'COMPLETED',to:'RECOGNIZED',permission:'research.approve.level4',actionType:'RECOGNIZE',decisionGate:true,aiAssist:true}
]}
function researchDocumentList(list){if(!list.length)return '<div class="empty">Chưa có tài liệu hồ sơ.</div>';return `<div class="timeline">${list.map(d=>`<div class="item"><div class="split"><div><strong>${esc(d.title||d.originalName)}</strong> <span class="pill ${d.extractionStatus==='EXTRACTED'?'ok':d.extractionStatus==='FAILED'?'warn':''}">${esc(d.extractionStatus||'STORED')}</span></div><button class="btn sm red" data-delete-rdoc="${esc(d.id)}">Xóa</button></div><div class="note">${esc(d.purpose||'SUPPORTING')} · ${fmt(d.createdAt)} ${d.fileUrl?`· <a href="${esc(d.fileUrl)}">Tải tệp</a>`:''}</div>${d.extractionMessage?`<div class="note warn-text">${esc(d.extractionMessage)}</div>`:''}${d.extractedPreview?`<p class="doc-preview">${esc(d.extractedPreview)}</p>`:''}</div>`).join('')}</div>`}
function researchDocumentModal(rid){modal(`<h3>Tải tài liệu vào hồ sơ</h3><form id="rdf"><div class="row"><div class="field"><span>Loại tài liệu</span><select name="purpose"><option value="REGISTRATION">Hồ sơ đăng ký</option><option value="PROPOSAL">Thuyết minh / đề cương</option><option value="PROGRESS">Báo cáo tiến độ</option><option value="RESULT">Báo cáo kết quả</option><option value="COUNCIL">Tài liệu hội đồng</option><option value="SUPPORTING">Tài liệu hỗ trợ khác</option></select></div><div class="field"><span>Tên hiển thị (chỉ dùng khi 1 tệp)</span><input name="title" placeholder="Tự lấy tên file nếu để trống"></div></div><div class="field"><span>Chọn nhiều tệp PDF / DOC / DOCX / TXT</span><input id="researchDocFiles" type="file" multiple accept=".pdf,.doc,.docx,.txt,.md,.rtf"><div id="researchDocFilesList" class="file-stack"></div></div><div class="actions"><button type="button" data-close class="btn">Hủy</button><button class="btn primary">Tải lên & trích xuất</button></div></form>`);const picker=setupMultiFileInput('#researchDocFiles','#researchDocFilesList');$('#rdf').onsubmit=async e=>{e.preventDefault();try{const base=Object.fromEntries(new FormData(e.target));delete base.researchDocFiles;base.files=await filesPayload(picker.files());if(!base.files.length)throw new Error('Chưa chọn tệp.');await api(`/api/research/${rid}/documents`,{method:'POST',body:JSON.stringify(base)});closeModal();openResearch(rid)}catch(x){showError(x)}}}

function councilModal(rid){modal(`<h3>Kết quả hội đồng</h3><form id="cf"><div class="row"><div class="field"><span>Ngày họp</span><input name="meetingDate" type="date" required></div><div class="field"><span>Kết quả</span><select name="result"><option>Đạt</option><option>Đạt có chỉnh sửa</option><option>Không đạt</option></select></div></div><div class="field"><span>Điểm (tùy chọn)</span><input name="score" type="number" step="0.1" min="0" max="100"></div><div class="field"><span>Biên bản / kết luận</span><textarea name="minutes"></textarea></div><div class="actions"><button type="button" data-close class="btn">Hủy</button><button class="btn primary">Lưu kết quả</button></div></form>`);$('#cf').onsubmit=async e=>{e.preventDefault();try{await api(`/api/research/${rid}/council`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();openResearch(rid)}catch(x){showError(x)}}}
function recognizeModal(rid){modal(`<h3>Công nhận hoàn thành</h3><form id="recf"><div class="row"><div class="field"><span>Số quyết định</span><input name="decisionNo" required></div><div class="field"><span>Ngày quyết định</span><input type="date" name="decisionDate" required></div></div><div class="field"><span>Ghi chú</span><textarea name="note"></textarea></div><div class="actions"><button type="button" data-close class="btn">Hủy</button><button class="btn primary">Công nhận</button></div></form>`);$('#recf').onsubmit=async e=>{e.preventDefault();if(!confirm('Xác nhận công nhận hoàn thành hồ sơ này?'))return;try{await api(`/api/research/${rid}/recognize`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();openResearch(rid)}catch(x){showError(x)}}}

function evidenceList(list){if(!list?.length)return '<div class="empty">Chưa có minh chứng.</div>';return `<div class="timeline">${list.map(e=>`<div class="item"><div class="split"><div><strong>${esc(e.title)}</strong> <span class="pill ${e.status==='VERIFIED'?'ok':e.status==='REJECTED'?'warn':''}">${esc(e.status)}</span></div><button class="btn sm red" data-delete-evidence="${esc(e.id)}">Xóa</button></div><div class="note">Mã: ${esc(e.code)} · ${fmt(e.createdAt)} ${e.fileUrl?`· <a href="${esc(e.fileUrl)}">Tải tệp</a>`:''}${e.url?`· <a target="_blank" rel="noopener" href="${esc(e.url)}">Liên kết</a>`:''}</div>${has('evidence.verify')&&e.status==='SUBMITTED'?`<div style="margin-top:7px"><button class="btn sm" data-verify="${esc(e.id)}" data-ok="1">Xác nhận</button> <button class="btn sm red" data-verify="${esc(e.id)}" data-ok="0">Từ chối</button></div>`:''}</div>`).join('')}</div>`}
function evidenceModal(rid){modal(`<h3>Thêm minh chứng</h3><form id="ef"><div class="row"><div class="field"><span>Mã minh chứng</span><input name="code" value="GENERAL" required></div><div class="field"><span>Tên minh chứng (nếu 1 tệp)</span><input name="title"></div></div><div class="field"><span>Liên kết (tùy chọn)</span><input name="url" type="url"></div><div class="field"><span>Tệp minh chứng — chọn nhiều tệp</span><input id="evidenceFiles" type="file" multiple><div id="evidenceFilesList" class="file-stack"></div></div><div class="actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn primary">Gửi minh chứng</button></div></form>`);const picker=setupMultiFileInput('#evidenceFiles','#evidenceFilesList');$('#ef').onsubmit=async e=>{e.preventDefault();const fd=Object.fromEntries(new FormData(e.target));try{const payload={code:fd.code,title:fd.title,url:fd.url||null,files:await filesPayload(picker.files())};if(!payload.files.length&&!payload.url)throw new Error('Cần chọn tệp hoặc nhập liên kết minh chứng.');await api(`/api/research/${rid}/evidence`,{method:'POST',body:JSON.stringify(payload)});closeModal();openResearch(rid)}catch(x){showError(x)}}}

function bytesToBase64(bytes){let s='';const chunk=0x8000;for(let i=0;i<bytes.length;i+=chunk)s+=String.fromCharCode(...bytes.subarray(i,i+chunk));return btoa(s)}
async function ai(){const providers=has('ai.configure')?await api('/api/ai/providers').catch(()=>[]):[];const enabled=providers.filter(p=>p.enabled!==false&&p.model&&!isLegacyDemoProvider(p));await syncAISettingsFromRegistry().catch(()=>null);const bc=getAISettings();const real=aiBrowserEnabled();$('#view').innerHTML=`<div class="page-head"><div><h2>AI Research Copilot</h2><p>Nhập nội dung hoặc tải nhiều PDF/DOC/DOCX/TXT. AI Router tự chọn provider/model phù hợp và fallback khi cần.</p></div></div><div class="ai-studio"><div class="card ai-compose"><div class="ai-orb">AI</div><div class="field"><span>Nhiệm vụ nghiên cứu</span><select id="task"><option>Phản biện đề cương nghiên cứu</option><option>Đánh giá tính nhất quán mục tiêu - phương pháp - sản phẩm</option><option>Gợi ý cấu trúc báo cáo kết quả</option><option>Kiểm tra danh mục minh chứng cần bổ sung</option></select></div><div class="field"><span>Nội dung cần phân tích</span><textarea id="aiContent" style="min-height:220px" placeholder="Có thể để trống nếu đã tải tệp..."></textarea></div><div class="field"><span>Tệp cần AI đọc — chọn nhiều tệp</span><input id="aiFiles" type="file" multiple accept=".pdf,.doc,.docx,.txt,.md,.rtf"><div id="aiFilesList" class="file-stack"></div></div><div class="split"><span class="ai-status ${enabled.length?'ready':''}"><i></i>${real?`AI thật: ${esc(bc.provider)} · ${esc(bc.model)}`:'Chưa có AI thật đang hoạt động'}</span><button class="btn primary" id="runAI">Phân tích bằng AI →</button></div><div id="aiResult" style="margin-top:16px"></div></div><aside class="card"><div class="kicker">CAPABILITY-FIRST MULTI-AI</div><h3>Phân tích đa tài liệu</h3><p class="note">RIS trích xuất nội dung từ các tệp và ghép ngữ cảnh trước khi gọi <span class="code">ai.inference</span>. Tệp không có lớp text sẽ hiển thị trạng thái để người dùng biết.</p></aside></div>`;const picker=setupMultiFileInput('#aiFiles','#aiFilesList');$('#runAI').onclick=async()=>{const box=$('#aiResult');box.className='ai-output';box.textContent='AI Router đang đọc tài liệu và phân tích...';try{const x=await api('/api/ai/assist',{method:'POST',body:JSON.stringify({route:'general',task:$('#task').value,content:$('#aiContent').value,files:await filesPayload(picker.files())})});box.textContent=`${x.result}

[Đã dùng: ${x.provider?.name||''} / ${x.provider?.model||''}]`}catch(e){box.textContent=e.message}}}

async function users(){const [list,roles,orgs]=await Promise.all([api('/api/users'),api('/api/roles'),api('/api/organizations')]);const om=Object.fromEntries(orgs.map(o=>[o.id,o]));$('#view').innerHTML=`<div class="page-head"><div><h2>Tài khoản</h2><p>Admin cấp tài khoản, vai trò và đơn vị quản lý.</p></div><button class="btn primary" id="newUser">+ Tài khoản</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Họ tên</th><th>Tài khoản</th><th>Đơn vị</th><th>Vai trò</th><th>Trạng thái</th></tr></thead><tbody>${list.map(u=>`<tr><td>${esc(u.displayName)}</td><td class="code">${esc(u.username)}</td><td>${esc(om[u.organizationId]?.name||'Chưa gán')}</td><td>${esc(u.roles.join(', '))}</td><td>${esc(u.status)}</td></tr>`).join('')}</tbody></table></div>`;$('#newUser').onclick=()=>modal(`<h3>Tạo tài khoản</h3><form id="uf"><div class="row"><div class="field"><span>Họ tên</span><input name="displayName" required></div><div class="field"><span>Tài khoản</span><input name="username" required></div></div><div class="field"><span>Mật khẩu khởi tạo</span><input type="password" name="password" minlength="10" required></div><div class="row"><div class="field"><span>Đơn vị</span><select name="organizationId" required><option value="">-- Chọn đơn vị --</option>${orgs.filter(o=>o.active!==false).map(o=>`<option value="${esc(o.id)}">${esc(o.name)}</option>`).join('')}</select></div><div class="field"><span>Vai trò</span><select name="role" required><option value="">-- Chọn vai trò --</option>${roles.map(r=>`<option value="${esc(r.code)}">${esc(r.name)}</option>`).join('')}</select></div></div><div class="actions"><button type="button" data-close class="btn">Hủy</button><button class="btn primary">Tạo</button></div></form>`);document.addEventListener('submit',async e=>{if(e.target.id!=='uf')return;e.preventDefault();const f=Object.fromEntries(new FormData(e.target));try{await api('/api/users',{method:'POST',body:JSON.stringify({displayName:f.displayName,username:f.username,password:f.password,organizationId:f.organizationId||null,roles:f.role?[f.role]:[]})});closeModal();users()}catch(x){showError(x)}},{once:true})}
async function organizations(){const list=await api('/api/organizations');const map=Object.fromEntries(list.map(o=>[o.id,o]));$('#view').innerHTML=`<div class="page-head"><div><h2>Đơn vị</h2><p>Quản lý Khoa, Bộ môn, Phòng, Trung tâm và các đơn vị khác. Người dùng và hồ sơ nghiên cứu được gắn đơn vị để phân quyền/phân tích theo phạm vi.</p></div><button class="btn primary" id="newOrg">+ Đơn vị</button></div>${list.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Mã</th><th>Tên đơn vị</th><th>Loại</th><th>Cấp trên</th><th>Trạng thái</th><th></th></tr></thead><tbody>${list.map(o=>`<tr><td class="code">${esc(o.code)}</td><td><b>${esc(o.name)}</b></td><td>${esc(o.type||'UNIT')}</td><td>${esc(map[o.parentId]?.name||'—')}</td><td>${o.active!==false?'Hoạt động':'Ngừng'}</td><td><button class="btn sm" data-edit-org="${esc(o.id)}">Sửa</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Chưa cấu hình đơn vị.</div>'}`;const edit=o=>{modal(`<h3>${o?'Sửa':'Thêm'} đơn vị</h3><form id="orgf"><input type="hidden" name="id" value="${esc(o?.id||'')}"><div class="row"><div class="field"><span>Mã đơn vị</span><input name="code" value="${esc(o?.code||'')}" required></div><div class="field"><span>Tên đơn vị</span><input name="name" value="${esc(o?.name||'')}" required></div></div><div class="row"><div class="field"><span>Loại</span><select name="type">${['UNIVERSITY','FACULTY','DEPARTMENT','CENTER','OFFICE','UNIT'].map(x=>`<option ${o?.type===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><span>Đơn vị cấp trên</span><select name="parentId"><option value="">-- Không có --</option>${list.filter(x=>x.id!==o?.id).map(x=>`<option value="${esc(x.id)}" ${o?.parentId===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div></div><label class="default-provider"><input type="checkbox" name="active" ${o?.active!==false?'checked':''}><span><b>Đang hoạt động</b></span></label><div class="actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn primary">Lưu đơn vị</button></div></form>`);$('#orgf').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));f.active=e.target.elements.active.checked;try{await api('/api/organizations',{method:'POST',body:JSON.stringify(f)});closeModal();organizations()}catch(x){showError(x)}}};$('#newOrg').onclick=()=>edit(null);document.querySelectorAll('[data-edit-org]').forEach(b=>b.onclick=()=>edit(list.find(o=>o.id===b.dataset.editOrg)))}
async function roles(){const list=await api('/api/roles');$('#view').innerHTML=`<div class="page-head"><div><h2>Vai trò</h2><p>Phân quyền theo capability.</p></div><button class="btn primary" id="newRole">+ Vai trò</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Mã</th><th>Tên</th><th>Quyền</th></tr></thead><tbody>${list.map(r=>`<tr><td class="code">${esc(r.code)}</td><td>${esc(r.name)}</td><td>${esc((r.permissions||[]).join(', '))}</td></tr>`).join('')}</tbody></table></div>`;$('#newRole').onclick=()=>modal(`<h3>Tạo vai trò</h3><form id="rolef"><div class="field"><span>Mã vai trò</span><input name="code" placeholder="LECTURER" required></div><div class="field"><span>Tên</span><input name="name" required></div><div class="field"><span>Permissions, phân cách dấu phẩy</span><textarea name="permissions" placeholder="research.create, research.read.self, evidence.upload"></textarea></div><div class="actions"><button type="button" data-close class="btn">Hủy</button><button class="btn primary">Tạo</button></div></form>`);document.addEventListener('submit',async e=>{if(e.target.id!=='rolef')return;e.preventDefault();const f=Object.fromEntries(new FormData(e.target));try{await api('/api/roles',{method:'POST',body:JSON.stringify({code:f.code,name:f.name,permissions:String(f.permissions).split(',').map(x=>x.trim()).filter(Boolean)})});closeModal();roles()}catch(x){showError(x)}},{once:true})}
async function types(){const list=await api('/api/research-types');$('#view').innerHTML=`<div class="page-head"><div><h2>Loại nghiên cứu</h2><p>Không hard-code đề tài, bài báo hay sáng kiến. Admin tự cấu hình loại hoạt động.</p></div><button class="btn primary" id="newType">+ Loại nghiên cứu</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Mã</th><th>Tên</th><th>Mô tả</th></tr></thead><tbody>${list.map(t=>`<tr><td class="code">${esc(t.code)}</td><td>${esc(t.name)}</td><td>${esc(t.description)}</td></tr>`).join('')}</tbody></table></div>`;$('#newType').onclick=()=>modal(`<h3>Tạo loại nghiên cứu</h3><form id="tf"><div class="row"><div class="field"><span>Mã</span><input name="code" placeholder="DE_TAI_CAP_TRUONG" required></div><div class="field"><span>Tên</span><input name="name" required></div></div><div class="field"><span>Mô tả</span><textarea name="description"></textarea></div><div class="actions"><button type="button" data-close class="btn">Hủy</button><button class="btn primary">Tạo</button></div></form>`);document.addEventListener('submit',async e=>{if(e.target.id!=='tf')return;e.preventDefault();try{await api('/api/research-types',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();types()}catch(x){showError(x)}},{once:true})}
async function workflows(){const [types,wfs]=await Promise.all([api('/api/research-types'),api('/api/workflows')]);$('#view').innerHTML=`<div class="page-head"><div><h2>Quy trình</h2><p>Mỗi loại nghiên cứu có workflow riêng. Có thể tải nhiều quy định/quy trình để AI đọc cùng lúc và chỉ ra mâu thuẫn.</p></div><button class="btn primary" id="newWf">+ Cấu hình</button></div>${wfs.length?`<div class="grid">${wfs.map(w=>`<div class="card"><div class="split"><div><strong>${esc(types.find(t=>t.id===w.researchTypeId)?.name||'Loại đã xóa')}</strong><p class="note">Khởi đầu: ${esc(w.initialStatus)} · ${w.transitions.length} bước chuyển</p></div><span class="pill">${(w.sourceDocuments||[]).length} tệp nguồn</span></div>${(w.sourceDocuments||[]).length?`<div class="file-stack">${w.sourceDocuments.map(d=>`<span class="file-chip"><a href="${esc(d.fileUrl)}">${esc(d.originalName)} · ${esc(d.analysisReady&&!d.hasExtractedText?'AI_NATIVE_READY':d.extractionStatus)}</a><button type="button" data-del-wfdoc="${esc(w.id)}|${esc(d.id||d.storedName)}">×</button></span>`).join('')}</div>`:''}<div class="timeline">${w.transitions.map(t=>`<div class="item"><span class="code">${esc(t.from)}</span> → <span class="code">${esc(t.to)}</span>${t.permission?` · quyền: ${esc(t.permission)}`:''}${t.actionType?` · ${esc(t.actionType)}`:''}${t.aiAssist?' · Human+AI':''}${t.requiredEvidence?.length?`<div class="note">Minh chứng: ${esc(t.requiredEvidence.join(', '))}</div>`:''}</div>`).join('')}</div>${(w.sourceDocuments||[]).length?`<div class="actions"><button class="btn sm" data-apply-4="${esc(w.id)}">Áp dụng mẫu duyệt 4 cấp</button><button class="btn primary sm" data-analyze-wf="${esc(w.id)}">AI phân tích toàn bộ tài liệu</button></div>`:''}</div>`).join('')}</div>`:'<div class="empty">Chưa có quy trình.</div>'}`;$('#newWf').onclick=()=>{modal(`<h3>Cấu hình quy trình</h3><form id="wff"><div class="field"><span>Loại nghiên cứu</span><select name="researchTypeId" required>${types.map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('')}</select></div><div class="field"><span>Tên quy trình</span><input name="name" value="Quy trình xét duyệt"></div><div class="field"><span>Trạng thái đầu</span><input name="initialStatus" value="DRAFT"></div><div class="field"><span>Tài liệu quy trình/quy định — nhiều tệp</span><input id="workflowSourceFiles" type="file" multiple accept=".pdf,.doc,.docx,.txt,.md,.rtf"><div id="workflowSourceFilesList" class="file-stack"></div></div><div class="field"><span>Các bước chuyển (JSON)</span><textarea name="transitions" style="min-height:280px">[{"from":"DRAFT","to":"SUBMITTED","permission":"research.submit","actionType":"SUBMIT","requiredEvidence":["REGISTRATION"]},{"from":"SUBMITTED","to":"LEVEL2_APPROVED","permission":"research.approve.level2","actionType":"APPROVE_LEVEL_2","decisionGate":true,"aiAssist":true},{"from":"SUBMITTED","to":"REVISION_REQUIRED","permission":"research.approve.level2","actionType":"RETURN_LEVEL_2","decisionGate":true,"aiAssist":true},{"from":"REVISION_REQUIRED","to":"SUBMITTED","permission":"research.submit","actionType":"RESUBMIT","requiredEvidence":["REGISTRATION"]},{"from":"LEVEL2_APPROVED","to":"LEVEL3_APPROVED","permission":"research.approve.level3","actionType":"APPROVE_LEVEL_3","decisionGate":true,"aiAssist":true},{"from":"LEVEL2_APPROVED","to":"REVISION_REQUIRED","permission":"research.approve.level3","actionType":"RETURN_LEVEL_3","decisionGate":true,"aiAssist":true},{"from":"LEVEL3_APPROVED","to":"APPROVED","permission":"research.approve.level4","actionType":"APPROVE_LEVEL_4","decisionGate":true,"aiAssist":true},{"from":"LEVEL3_APPROVED","to":"REVISION_REQUIRED","permission":"research.approve.level4","actionType":"RETURN_LEVEL_4","decisionGate":true,"aiAssist":true},{"from":"APPROVED","to":"IN_PROGRESS","permission":"research.submit","actionType":"START"},{"from":"IN_PROGRESS","to":"RESULT_SUBMITTED","permission":"research.submit","actionType":"SUBMIT_RESULT","requiredEvidence":["RESULT"]},{"from":"RESULT_SUBMITTED","to":"COUNCIL_REVIEW","permission":"research.approve.level2","actionType":"SEND_COUNCIL","decisionGate":true,"aiAssist":true},{"from":"COUNCIL_REVIEW","to":"COMPLETED","permission":"council.manage","actionType":"APPROVE_COUNCIL","decisionGate":true,"aiAssist":true},{"from":"COUNCIL_REVIEW","to":"IN_PROGRESS","permission":"council.manage","actionType":"RETURN","decisionGate":true,"aiAssist":true},{"from":"COMPLETED","to":"RECOGNIZED","permission":"research.approve.level4","actionType":"RECOGNIZE","decisionGate":true,"aiAssist":true}]</textarea></div><div class="actions"><button type="button" data-close class="btn">Hủy</button><button class="btn primary">Lưu</button></div></form>`);const picker=setupMultiFileInput('#workflowSourceFiles','#workflowSourceFilesList');$('#wff').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));delete f.workflowSourceFiles;try{f.transitions=JSON.parse(f.transitions);f.sourceFiles=await filesPayload(picker.files());await api('/api/workflows',{method:'POST',body:JSON.stringify(f)});closeModal();workflows()}catch(x){showError(x)}}};document.querySelectorAll('[data-apply-4]').forEach(b=>b.onclick=async()=>{const w=wfs.find(x=>x.id===b.dataset.apply4);if(!w||!confirm('Thay các bước chuyển hiện tại bằng mẫu phê duyệt 4 cấp? Tài liệu nguồn vẫn được giữ nguyên.'))return;try{await api('/api/workflows',{method:'POST',body:JSON.stringify({researchTypeId:w.researchTypeId,name:w.name,initialStatus:w.initialStatus||'DRAFT',transitions:approvalWorkflowTemplate(),sourceFiles:[]})});workflows()}catch(e){showError(e)}});document.querySelectorAll('[data-analyze-wf]').forEach(b=>b.onclick=async()=>{try{b.disabled=true;b.textContent='AI đang phân tích...';const x=await api(`/api/workflows/${b.dataset.analyzeWf}/analyze`,{method:'POST',body:'{}'});modal(`<h3>AI phân tích tài liệu quy trình</h3><pre class="ai-doc-analysis">${esc(x.result)}</pre><div class="actions"><button class="btn primary" data-close>Đóng</button></div>`)}catch(e){showError(e)}finally{b.disabled=false;b.textContent='AI phân tích toàn bộ tài liệu'}})};document.querySelectorAll('[data-del-wfdoc]').forEach(b=>b.onclick=async()=>{const [wid,did]=b.dataset.delWfdoc.split('|');if(!confirm('Xóa tệp nguồn quy trình này?'))return;try{await api(`/api/workflows/${wid}/source-documents/${did}`,{method:'DELETE'});workflows()}catch(e){showError(e)}})

async function aiSettings(){
  const cfg=getAISettings();
  const providerLabels={openai:'OpenAI',gemini:'Google Gemini',anthropic:'Anthropic',openrouter:'OpenRouter'};
  $('#view').innerHTML=`<div class="page-head"><div><h2>AI Settings</h2><p>GitHub Pages chỉ chạy trong trình duyệt. Chế độ Demo không cần khóa; BYOK dùng khóa của chính người thử và chỉ giữ trong session hiện tại.</p></div></div>
  <div class="grid"><div class="card"><form id="aiBrowserForm">
    <div class="field"><span>Chế độ AI</span><select name="mode"><option value="demo" ${cfg.mode!=='byok'?'selected':''}>Demo AI — không cần API key</option><option value="byok" ${cfg.mode==='byok'?'selected':''}>BYOK — AI thật từ trình duyệt</option></select></div>
    <div class="row"><div class="field"><span>Provider</span><select name="provider"><option value="openai" ${cfg.provider==='openai'?'selected':''}>OpenAI</option><option value="gemini" ${cfg.provider==='gemini'?'selected':''}>Google Gemini</option><option value="anthropic" ${cfg.provider==='anthropic'?'selected':''}>Anthropic</option><option value="openrouter" ${cfg.provider==='openrouter'?'selected':''}>OpenRouter</option></select></div><div class="field"><span>Model ID</span><input name="model" value="${esc(cfg.model||'')}" placeholder="Ví dụ: model sinh văn bản bạn được cấp quyền"></div></div>
    <div class="field"><span>API key</span><div class="inline"><input id="browserAIKey" name="apiKey" type="password" value="${esc(cfg.apiKey||'')}" autocomplete="off" placeholder="Chỉ lưu trong sessionStorage"><button type="button" class="btn sm" id="showBrowserKey">Hiện</button></div><small class="field-help">Không commit khóa vào GitHub. Khóa bị xóa khi đóng tab/browser session hoặc khi bấm Xóa khóa.</small></div>
    <div class="field"><span>Base URL tùy chọn</span><input name="baseUrl" value="${esc(cfg.baseUrl||'')}" placeholder="Để trống để dùng endpoint mặc định"></div>
    <div class="actions"><button type="button" class="btn" id="testBrowserAI">Kiểm tra AI thật</button><button type="button" class="btn danger" id="clearBrowserAI">Xóa khóa</button><button class="btn primary">Lưu cho phiên làm việc</button></div>
  </form><div id="browserAIStatus" style="margin-top:14px"></div></div>
  <div class="card"><div class="kicker">BẢO MẬT TRÊN GITHUB PAGES</div><h3>BYOK không phải cấu hình production</h3><p class="note">API key tồn tại trong trình duyệt của người dùng và request đi trực tiếp tới provider. Không có khóa nào được lưu vào repository hay localStorage. Một số provider/model có thể chặn request từ trình duyệt bằng CORS; khi đó RIS sẽ báo lỗi rõ ràng, không giả lập kết quả AI thật.</p><div class="ai-security"><b>Trạng thái hiện tại</b><p>${cfg.mode==='byok'&&cfg.apiKey&&cfg.model?`BYOK: ${esc(providerLabels[cfg.provider]||cfg.provider)} · ${esc(cfg.model)}`:'Demo AI'}</p></div></div></div>`;
  const form=$('#aiBrowserForm');
  $('#showBrowserKey').onclick=()=>{const i=$('#browserAIKey');i.type=i.type==='password'?'text':'password';$('#showBrowserKey').textContent=i.type==='password'?'Hiện':'Ẩn'};
  form.onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(form));saveAISettings(f);$('#browserAIStatus').innerHTML='<div class="success">Đã lưu cấu hình AI cho phiên làm việc này.</div>';setTimeout(()=>aiSettings(),500)};
  $('#clearBrowserAI').onclick=()=>{clearAISettings();$('#browserAIStatus').innerHTML='<div class="success">Đã xóa API key. Các chức năng yêu cầu AI thật sẽ tạm dừng cho tới khi cấu hình lại provider.</div>';setTimeout(()=>aiSettings(),500)};
  $('#testBrowserAI').onclick=async()=>{const b=$('#testBrowserAI'),box=$('#browserAIStatus');const f=Object.fromEntries(new FormData(form));saveAISettings(f);if(f.mode!=='byok'){box.innerHTML='<div class="note">Đang ở Demo AI; không có kết nối provider thật để kiểm tra.</div>';return}try{b.disabled=true;b.textContent='Đang kiểm tra...';const r=await realAIInfer({task:'Kiểm tra kết nối',content:'Chỉ trả lời một câu ngắn xác nhận kết nối thành công.'});box.innerHTML=`<div class="success">Kết nối thành công: ${esc(r.provider.name)} / ${esc(r.provider.model)}</div><div class="ai-output">${esc(r.result)}</div>`}catch(e){box.innerHTML=`<div class="error">${esc(e.message)}</div>`}finally{b.disabled=false;b.textContent='Kiểm tra AI thật'}};
}

async function aiDecisionCenter(){
  const [d,autopilot]=await Promise.all([api('/api/ai/decision-center'),api('/api/ai/autopilot').catch(()=>({enabled:false}))]);
  const v6=window.NuteAIActivity?.summary?.()||{policies:[],recommendations:[],decisions:[],counts:{events:0,analyzed:0,awaitingHuman:0,failed:0}};
  d.recommendations=[...(v6.recommendations||[]),...(d.recommendations||[])];
  d.decisions=[...(v6.decisions||[]),...(d.decisions||[])];
  d.counts={pending:(d.counts?.pending||0),analyzed:(d.counts?.analyzed||0)+(v6.counts?.analyzed||0),awaitingHuman:(d.counts?.awaitingHuman||0)+(v6.counts?.awaitingHuman||0)};
  const pending=(d.workItems||[]).filter(x=>x.status==='PENDING');
  const recMap=new Map((d.recommendations||[]).map(x=>[x.id,x]));
  const decMap=new Map((d.decisions||[]).map(x=>[x.recommendationId,x]));
  $('#view').innerHTML=`<div class="page-head"><div><h2>AI Decision Center</h2><p>Trung tâm điều phối trí tuệ của RIS. AI không đứng ngoài quy trình: mỗi sự kiện nghiên cứu sinh ra một nhiệm vụ phân tích và một khuyến nghị để con người xem xét.</p></div><div class="actions">${has('ai.decision.manage')?`<button class="btn ${autopilot.enabled?'primary':''}" id="toggleAutopilot">AI Autopilot: ${autopilot.enabled?'BẬT':'TẮT'}</button>`:''}${has('ai.portfolio')?'<button class="btn primary" id="portfolioAI">AI phân tích danh mục →</button>':''}</div></div>
  <div class="grid cards decision-metrics"><div class="card metric"><div class="label">Điểm quyết định đang chờ AI</div><div class="num">${d.counts.pending}</div></div><div class="card metric"><div class="label">Đã được AI phân tích</div><div class="num">${d.counts.analyzed}</div></div><div class="card metric"><div class="label">Chờ con người xem xét</div><div class="num">${d.counts.awaitingHuman}</div></div><div class="card metric intelligence"><div class="label">Mô hình vận hành</div><div class="num small">Human + AI</div></div></div>
  <div class="ris-loop"><div><b>1. Sự kiện nghiệp vụ</b><span>Hồ sơ, minh chứng, chuyển bước, hội đồng...</span></div><i>→</i><div><b>2. AI phân tích</b><span>Dữ kiện · rủi ro · phương án</span></div><i>→</i><div><b>3. Con người quyết định</b><span>Chấp nhận · bác bỏ · điều chỉnh</span></div><i>→</i><div><b>4. Hệ thống học ngữ cảnh</b><span>Lưu vết quyết định để tham chiếu</span></div></div>
  <div class="card" style="margin-top:18px"><div class="split"><div><h3 style="margin:0 0 4px">Legacy AI Activity Policies · V7 compatibility</h3><span class="note">7 decision point Phase 1. ${aiBrowserEnabled()?'BYOK đã cấu hình; provider thực tế được ghi trên từng recommendation':'Đang dùng structured fallback; cấu hình BYOK để chạy AI thật'}.</span></div><span class="pill ${aiBrowserEnabled()?'ok':''}">${aiBrowserEnabled()?'BYOK CONFIGURED':'DEMO/FALLBACK'}</span></div><div class="decision-list" style="margin-top:14px">${(v6.policies||[]).map(p=>`<div class="decision-item"><div><strong>${esc(p.activity)}</strong><p>${esc(p.label||p.profile)}</p><small>${esc(p.profile)} · min confidence ${Math.round((p.minimumConfidence||0)*100)}%</small></div><div class="actions"><label class="note"><input type="checkbox" data-v6-policy-enabled="${esc(p.activity)}" ${p.enabled?'checked':''}> Bật</label><select data-v6-policy-autonomy="${esc(p.activity)}">${['OBSERVE_ONLY','ADVISORY','RECOMMEND','AUTO_REVERSIBLE','HUMAN_MANDATORY'].map(x=>`<option ${x===p.autonomy?'selected':''}>${x}</option>`).join('')}</select></div></div>`).join('')}</div></div>
  <div class="card" style="margin-top:18px"><div class="split"><div><h3 style="margin:0 0 4px">Hàng đợi điểm quyết định</h3><span class="note">Các nhiệm vụ được hệ thống tạo tự động khi RIS phát sinh sự kiện quan trọng.</span></div></div><div style="margin-top:14px">${pending.length?`<div class="decision-list">${pending.slice(0,30).map(w=>`<div class="decision-item"><div><span class="pill">${esc(w.decisionPoint)}</span><h4>${esc(w.label)}</h4><p>${esc(w.research?.title||'Hồ sơ nghiên cứu')}</p><small>${fmt(w.createdAt)}</small></div><button class="btn primary sm" data-process-ai="${esc(w.id)}">Phân tích</button></div>`).join('')}</div>`:'<div class="empty">Không có điểm quyết định đang chờ AI.</div>'}</div></div>
  <div class="card" style="margin-top:18px"><h3 style="margin-top:0">Khuyến nghị gần đây</h3>${(d.recommendations||[]).length?`<div class="decision-list">${d.recommendations.slice(0,20).map(r=>{const hd=decMap.get(r.id); const body=r.structured?.summary||r.structured?.recommendation?.reasoningSummary||r.structured?.recommendation||r.raw||'';return `<div class="recommendation"><div class="split"><div><span class="pill ${hd?'ok':''}">${hd?`Con người: ${esc(hd.outcome)}`:'CHỜ XEM XÉT'}</span><strong>${esc(r.decisionPoint)}</strong><small>${fmt(r.createdAt)}</small></div>${!hd&&has('ai.decision.manage')?`<div class="decision-actions"><button class="btn sm" data-ai-decision="${esc(r.id)}" data-outcome="ACCEPT">Chấp nhận</button><button class="btn sm" data-ai-decision="${esc(r.id)}" data-outcome="OVERRIDE">Điều chỉnh</button><button class="btn sm" data-ai-decision="${esc(r.id)}" data-outcome="REJECT">Bác bỏ</button></div>`:''}</div><p class="ai-rec-text">${esc(String(body).slice(0,900))}</p></div>`}).join('')}</div>`:'<div class="empty">Chưa có khuyến nghị AI.</div>'}</div>
  <div id="portfolioResult" style="margin-top:18px"></div>`;
  document.querySelectorAll('[data-v6-policy-enabled]').forEach(el=>el.onchange=()=>{try{window.NuteAIActivity.updatePolicy(el.dataset.v6PolicyEnabled,{enabled:el.checked})}catch(e){showError(e)}});
  document.querySelectorAll('[data-v6-policy-autonomy]').forEach(el=>el.onchange=()=>{try{window.NuteAIActivity.updatePolicy(el.dataset.v6PolicyAutonomy,{autonomy:el.value,requiresHumanDecision:el.value==='HUMAN_MANDATORY'||el.value==='RECOMMEND'})}catch(e){showError(e)}});
  document.querySelectorAll('[data-process-ai]').forEach(b=>b.onclick=async()=>{b.disabled=true;b.textContent='Đang phân tích...';try{await api(`/api/ai/work-items/${b.dataset.processAi}/process`,{method:'POST',body:'{}'});aiDecisionCenter()}catch(e){showError(e);b.disabled=false;b.textContent='Phân tích'}});
  document.querySelectorAll('[data-ai-decision]').forEach(b=>b.onclick=()=>humanAIDecision(b.dataset.aiDecision,b.dataset.outcome));
  if($('#toggleAutopilot'))$('#toggleAutopilot').onclick=async()=>{try{await api('/api/ai/autopilot',{method:'POST',body:JSON.stringify({enabled:!autopilot.enabled})});aiDecisionCenter()}catch(e){showError(e)}};
  if($('#portfolioAI'))$('#portfolioAI').onclick=async()=>{const box=$('#portfolioResult');box.className='card ai-output';box.textContent='AI đang phân tích danh mục nghiên cứu toàn hệ thống...';try{const r=await api('/api/ai/portfolio/analyze',{method:'POST',body:'{}'});box.textContent=r.result}catch(e){box.textContent=e.message}};
}
