async function knowledgePage(){const list=await api('/api/knowledge');$('#view').innerHTML=`<div class="page-head"><div><h2>Kho tri thức & Quy chế</h2><p>Tải nhiều tệp quy định/quy chế; RIS trích xuất văn bản và AI phân tích trực tiếp các tài liệu đã lưu.</p></div><button class="btn primary" id="newKnowledge">+ Tài liệu tri thức</button></div>${list.length?`<div class="knowledge-grid">${list.map(d=>`<div class="card"><div class="split"><span class="pill">${esc(d.kind)}</span><small>${esc(d.scope)}</small></div><h3>${esc(d.title)}</h3><p class="note">${esc(d.contentPreview||'')}</p><div class="file-stack">${(d.sourceDocuments||[]).map(f=>`<span class="file-chip"><a href="${esc(f.fileUrl)}">${esc(f.originalName)} · ${esc(f.analysisReady&&!f.hasExtractedText?'AI_NATIVE_READY':f.extractionStatus)}</a><button type="button" data-del-kfile="${esc(d.id)}|${esc(f.id||f.storedName)}">×</button></span>`).join('')}</div><div class="actions"><button class="btn sm" data-edit-k="${esc(d.id)}">Sửa / thêm tệp</button><button class="btn primary sm" data-analyze-k="${esc(d.id)}">AI phân tích</button></div>${d.aiAnalysis?`<div class="success">Đã phân tích: ${fmt(d.aiAnalysis.at)}</div>`:''}</div>`).join('')}</div>`:'<div class="empty">Kho tri thức đang trống.</div>'}`;$('#newKnowledge').onclick=()=>knowledgeModal(null);document.querySelectorAll('[data-edit-k]').forEach(b=>b.onclick=()=>knowledgeModal(list.find(x=>x.id===b.dataset.editK)));document.querySelectorAll('[data-analyze-k]').forEach(b=>b.onclick=async()=>{try{b.disabled=true;b.textContent='AI đang đọc...';const x=await api(`/api/knowledge/${b.dataset.analyzeK}/analyze`,{method:'POST',body:'{}'});modal(`<h3>AI phân tích quy định / tri thức</h3><pre class="ai-doc-analysis">${esc(x.result)}</pre><div class="actions"><button class="btn primary" data-close>Đóng</button></div>`)}catch(e){showError(e)}finally{b.disabled=false;b.textContent='AI phân tích'}})};document.querySelectorAll('[data-del-kfile]').forEach(b=>b.onclick=async()=>{const [kid,did]=b.dataset.delKfile.split('|');if(!confirm('Xóa tệp nguồn tri thức này?'))return;try{await api(`/api/knowledge/${kid}/source-documents/${did}`,{method:'DELETE'});knowledgePage()}catch(e){showError(e)}})
