async function providers(){
  const list=await api('/api/ai/providers');
  const caps=p=>Object.entries(p.capabilities||{}).filter(([k,v])=>v&&k!=='chat').map(([k])=>`<span class="cap-chip">${esc(capLabel(k))}</span>`).join('')||'<span class="cap-chip quiet">Safe default</span>';
  $('#view').innerHTML=`<div class="page-head"><div><h2>AI Model Registry & Router</h2><p>RIS vận hành như một hệ sinh thái AI: nhiều provider/model có thể cùng hoạt động, được định tuyến theo capability và tự fallback khi model ưu tiên lỗi.</p></div><button class="btn primary" id="newP">+ Thêm mô hình AI</button></div>
  <div class="registry-note"><div class="registry-icon">AI</div><div><b>Multi-AI · Capability Routing · Fallback</b><span>Model discovery đã lọc các model không phù hợp cho sinh nội dung như embedding, audio, moderation và model legacy. Không còn tự chọn model đầu tiên như babbage-002.</span></div></div>
  ${list.length?`<div class="provider-grid">${list.map(p=>`<article class="provider-card ${p.primary?'active-provider':''} ${p.enabled===false?'provider-disabled':''}"><div class="provider-top"><div><span class="provider-kind">${esc(p.kind)}</span><h3>${esc(p.name)}</h3></div>${p.primary?'<span class="pill ok">Ưu tiên chính</span>':p.enabled===false?'<span class="pill warn">Tắt</span>':'<span class="pill">Fallback</span>'}</div><div class="model-id">${esc(p.model||'Chưa chọn model')}</div><div class="cap-list">${caps(p)}</div><div class="provider-meta"><span>${p.kind==='ollama'?'Local AI':(registrySecrets()[p.id]?'🔐 Key trong session':'🔑 Nhập key khi kiểm tra')}</span><span>Ưu tiên ${esc(p.priority??100)}</span><span>Route: ${esc((p.routes||['*']).join(', '))}</span></div><div class="provider-actions"><button class="btn sm" data-testp="${esc(p.id)}">Kiểm tra</button><button class="btn sm" data-editp="${esc(p.id)}">Cấu hình</button></div></article>`).join('')}</div>`:'<div class="empty">Chưa có mô hình AI. Có thể thêm OpenAI, Gemini, Anthropic, OpenRouter, Groq, Ollama hoặc API tương thích.</div>'}`;
  $('#newP').onclick=()=>providerModal(null);document.querySelectorAll('[data-editp]').forEach(b=>b.onclick=()=>providerModal(list.find(p=>p.id===b.dataset.editp)));document.querySelectorAll('[data-testp]').forEach(b=>b.onclick=async()=>{const p=list.find(x=>x.id===b.dataset.testp);try{b.disabled=true;b.textContent='Đang kiểm tra...';const x=await api('/api/ai/providers/test',{method:'POST',body:JSON.stringify({id:p.id})});alert(x.model?`Kết nối thành công với ${x.model}: ${x.response}`:`${x.response}`)}catch(e){showError(e)}finally{b.disabled=false;b.textContent='Kiểm tra'}});
}
function capLabel(k){return ({temperature:'Temperature',streaming:'Streaming',vision:'Vision',jsonMode:'JSON mode',reasoning:'Reasoning',toolCalling:'Tool calling',embeddings:'Embeddings',chat:'Chat'})[k]||k}
function providerModal(p){
  let discoveredModels=[];const c={chat:true,streaming:false,temperature:false,vision:false,jsonMode:false,reasoning:false,toolCalling:false,embeddings:false,...(p?.capabilities||{})};const g={useTemperature:false,temperature:0.2,useMaxTokens:false,maxTokens:1800,...(p?.generation||{})};const routes=p?.routes?.length?p.routes:['*'];
  modal(`<div class="modal-title"><div><span class="eyebrow">MULTI-AI REGISTRY</span><h3>${p?'Cấu hình':'Thêm'} mô hình AI</h3><p>Mỗi model là một implementation của capability AI. Router sẽ chọn theo route/priority và fallback khi cần.</p></div><span class="ai-model-orb">AI</span></div><form id="pf"><input type="hidden" name="id" value="${esc(p?.id||'')}">
  <div class="row"><div class="field"><span>Tên cấu hình</span><input name="name" value="${esc(p?.name||'')}" placeholder="Ví dụ: Gemini - Academic" required></div><div class="field"><span>Nhà cung cấp</span><select name="kind">${['openai','gemini','anthropic','openrouter','groq','ollama','custom'].map(k=>`<option ${p?.kind===k?'selected':''}>${k}</option>`).join('')}</select></div></div>
  <div class="field"><span>API Key · chỉ giữ trong session hiện tại</span><div class="secret"><input id="keyInput" type="password" name="apiKey" autocomplete="new-password" placeholder="Nhập API key; Ollama local có thể để trống"><button class="btn" type="button" id="showKey">Hiện</button></div></div>
  <details class="advanced"><summary>Cấu hình endpoint nâng cao</summary><div class="field"><span>API Endpoint</span><input name="endpoint" value="${esc(p?.endpoint||'')}" placeholder="Để trống để dùng endpoint mặc định"></div><div class="field"><span>Models Endpoint</span><input name="modelsEndpoint" value="${esc(p?.modelsEndpoint||'')}" placeholder="Để trống để hệ thống tự suy ra"></div></details>
  <div class="model-picker"><div class="field" style="margin:0"><span>Model ID</span><input id="modelInput" list="modelOptions" name="model" value="${esc(p?.model||'')}" placeholder="Bấm lấy model rồi tự chọn một model sinh nội dung"><datalist id="modelOptions"></datalist></div><button type="button" class="btn model-fetch" id="fetchModels">Kiểm tra key & lấy model</button></div><div class="discover-status" id="modelStatus">${p?.modelMetadata?.probedAt?`Capability gần nhất: ${fmt(p.modelMetadata.probedAt)}`:'Chưa dò capability của model.'}</div>
  <div class="card inset"><b>Định tuyến trong hệ sinh thái AI</b><div class="row" style="margin-top:12px"><div class="field"><span>Thứ tự ưu tiên</span><input type="number" name="priority" min="1" max="999" value="${esc(p?.priority??100)}"><small class="field-help">Số nhỏ được thử trước.</small></div><div class="field"><span>Capability routes</span><input name="routes" value="${esc(routes.join(', '))}" placeholder="* hoặc academic, decision, workflow, portfolio, general"><small class="field-help">Dùng * cho mọi nhiệm vụ; hoặc giới hạn model cho từng lớp AI.</small></div></div><div class="row"><label class="default-provider"><input type="checkbox" name="enabled" ${p?.enabled!==false?'checked':''}><span><b>Cho phép Router sử dụng</b><small>Tắt để giữ cấu hình nhưng không gọi model.</small></span></label><label class="default-provider"><input type="checkbox" name="primary" ${p?.primary||p?.active?'checked':''}><span><b>Ưu tiên chính</b><small>Provider chính được thử trước, nhưng provider khác vẫn là fallback.</small></span></label></div></div>
  <div class="capability-panel"><div class="capability-head"><div><b>Metadata capability</b><span>Chỉ bật những khả năng đã biết hoặc đã kiểm thử.</span></div><button type="button" class="btn sm" id="probeModel">Dò khả năng model</button></div><div class="capability-grid">${[['streaming','Streaming'],['temperature','Temperature'],['vision','Vision'],['jsonMode','JSON mode'],['reasoning','Reasoning'],['toolCalling','Tool calling'],['embeddings','Embeddings']].map(([k,label])=>`<label class="cap-toggle"><input type="checkbox" id="cap_${k}" ${c[k]?'checked':''}><span><b>${label}</b><small>${k==='temperature'?'Cho phép RIS gửi temperature tùy chỉnh':'Metadata cho Router / orchestration'}</small></span></label>`).join('')}</div></div>
  <div class="generation-panel"><b>Tham số sinh nội dung</b><p>Safe-by-default: chỉ gửi tham số tùy chọn khi model đã xác nhận hỗ trợ.</p><div class="row"><label class="switch-line"><input type="checkbox" id="useTemperature" ${g.useTemperature?'checked':''}><span>Dùng temperature</span><input class="compact-number" id="temperatureValue" type="number" min="0" max="2" step="0.1" value="${esc(g.temperature)}"></label><label class="switch-line"><input type="checkbox" id="useMaxTokens" ${g.useMaxTokens?'checked':''}><span>Giới hạn output tokens</span><input class="compact-number" id="maxTokensValue" type="number" min="1" max="32768" step="1" value="${esc(g.maxTokens)}"></label></div></div>
  <div class="actions"><button type="button" class="btn" id="testP">Kiểm tra kết nối</button><button type="button" data-close class="btn">Hủy</button><button class="btn primary">Lưu Registry</button></div></form>`);
  const form=$('#pf'),modelInput=$('#modelInput');const syncTemp=()=>{const supported=$('#cap_temperature').checked;$('#useTemperature').disabled=!supported;if(!supported)$('#useTemperature').checked=false;$('#temperatureValue').disabled=!supported||!$('#useTemperature').checked};$('#cap_temperature').onchange=syncTemp;$('#useTemperature').onchange=syncTemp;syncTemp();$('#showKey').onclick=()=>{const i=$('#keyInput');i.type=i.type==='password'?'text':'password';$('#showKey').textContent=i.type==='password'?'Hiện':'Ẩn'};
  $('#fetchModels').onclick=async()=>{const b=$('#fetchModels');try{b.disabled=true;b.textContent='Đang tải...';$('#modelStatus').textContent='Đang truy vấn và lọc model sinh nội dung...';const f=providerFormData(form);const x=await api('/api/ai/providers/models',{method:'POST',body:JSON.stringify(f)});discoveredModels=x.models||[];$('#modelOptions').innerHTML=discoveredModels.map(m=>`<option value="${esc(m.id)}">${esc(m.name||m.id)}</option>`).join('');$('#modelStatus').textContent=`Có ${x.count} model phù hợp cho sinh nội dung. Hãy chọn model; RIS không tự chọn model đầu tiên.`;if(!discoveredModels.length)throw new Error('Provider không trả về model sinh nội dung tương thích.')}catch(e){showError(e)}finally{b.disabled=false;b.textContent='Kiểm tra key & lấy model'}};
  $('#probeModel').onclick=async()=>{const b=$('#probeModel');try{b.disabled=true;b.textContent='Đang dò...';const f=providerFormData(form);if(!f.model)throw new Error('Hãy chọn Model ID trước.');const x=await api('/api/ai/providers/probe',{method:'POST',body:JSON.stringify(f)});if(!x.reachable)throw new Error(x.probes?.base?.error||'Không kết nối được model.');$('#cap_temperature').checked=!!x.capabilities?.temperature;syncTemp();$('#modelStatus').innerHTML=`<span class="status-ok">Kết nối OK</span> · Temperature: <b>${x.capabilities?.temperature?'hỗ trợ':'không hỗ trợ / chỉ mặc định'}</b>`}catch(e){showError(e)}finally{b.disabled=false;b.textContent='Dò khả năng model'}};
  $('#testP').onclick=async()=>{const b=$('#testP');try{b.disabled=true;b.textContent='Đang kiểm tra...';const f=providerFormData(form);const x=await api('/api/ai/providers/test',{method:'POST',body:JSON.stringify(f)});alert(x.model?`Kết nối thành công với ${x.model}: ${x.response}`:`${x.response}`)}catch(e){showError(e)}finally{b.disabled=false;b.textContent='Kiểm tra kết nối'}};
  form.onsubmit=async e=>{e.preventDefault();const f=providerFormData(e.target);if(!f.model){showError(new Error('Hãy lấy danh sách model và chủ động chọn một Model ID trước khi lưu.'));return;}const meta=discoveredModels.find(m=>m.id===f.model);if(meta)f.modelMetadata={...meta,discoveredAt:new Date().toISOString()};try{await api('/api/ai/providers',{method:'POST',body:JSON.stringify(f)});closeModal();providers()}catch(x){showError(x)}};
}
function providerFormData(form){const base=Object.fromEntries(new FormData(form));base.enabled=form.elements.enabled?.checked!==false;base.primary=form.elements.primary?.checked||false;base.active=base.primary;base.priority=Number(base.priority||100);base.routes=String(base.routes||'*').split(',').map(x=>x.trim()).filter(Boolean);base.capabilities={chat:true,streaming:$('#cap_streaming')?.checked||false,temperature:$('#cap_temperature')?.checked||false,vision:$('#cap_vision')?.checked||false,jsonMode:$('#cap_jsonMode')?.checked||false,reasoning:$('#cap_reasoning')?.checked||false,toolCalling:$('#cap_toolCalling')?.checked||false,embeddings:$('#cap_embeddings')?.checked||false};base.generation={useTemperature:$('#useTemperature')?.checked||false,temperature:Number($('#temperatureValue')?.value||0.2),useMaxTokens:$('#useMaxTokens')?.checked||false,maxTokens:Number($('#maxTokensValue')?.value||1800)};return base}

async function researchWorkspaceList(){
  const list=await api('/api/research');
  $('#view').innerHTML=`<div class="page-head"><div><h2>AI Research Workspace</h2><p>Không gian làm việc cho người tham gia nghiên cứu: quy trình, mốc công việc, nguồn học thuật và AI học thuật được gắn trực tiếp với từng hoạt động.</p></div></div>${list.length?`<div class="workspace-grid">${list.map(r=>`<article class="workspace-card"><div class="workspace-card-top"><span class="pill">${esc(r.status)}</span><span class="note">${esc(r.type?.name||'Hoạt động nghiên cứu')}</span></div><h3>${esc(r.title)}</h3><p>${esc(r.summary||'Chưa có tóm tắt.')}</p><button class="btn primary" data-workspace="${esc(r.id)}">Mở Research Workspace →</button></article>`).join('')}</div>`:'<div class="empty">Bạn chưa có hoạt động nghiên cứu nào.</div>'}`;
  document.querySelectorAll('[data-workspace]').forEach(b=>b.onclick=()=>openResearchWorkspace(b.dataset.workspace));
}

async function openResearchWorkspace(id){
  const ws=await api(`/api/research/${id}/workspace`); state.data.workspace=ws;
  const caps=ws.academicCapabilities||[];
  const next=(ws.process?.nextSteps||[]);
  const actions=(ws.process?.suggestedActions||[]);
  $('#view').innerHTML=`<div class="workspace-head"><button class="btn sm" id="backWorkspace">← Danh sách</button><div><span class="eyebrow">AI RESEARCH WORKSPACE</span><h2>${esc(ws.research.title)}</h2><p>${esc(ws.type?.name||'Hoạt động nghiên cứu')} · ${esc(ws.organization?.name||'Chưa gán đơn vị')} · <b>${esc(ws.research.status)}</b></p></div><span class="workspace-ai-orb">AI</span></div>
  <div class="workspace-layout"><main class="workspace-main">
    <section class="card process-card"><div class="split"><div><h3>Tôi đang ở đâu và cần làm gì tiếp?</h3><p class="note">RIS đọc workflow, minh chứng và mốc công việc để hướng dẫn theo trạng thái hiện tại.</p></div><span class="status-large">${esc(ws.process.currentStatus)}</span></div>
      <div class="process-actions">${actions.length?actions.map((a,i)=>`<div class="process-action"><span>${i+1}</span><p>${esc(a)}</p></div>`).join(''):'<div class="empty">Chưa có gợi ý quy trình.</div>'}</div>
      ${next.length?`<div class="next-steps">${next.map(n=>`<div><b>→ ${esc(n.to)}</b><small>${n.ready?'Đủ minh chứng cấu hình':'Thiếu: '+esc(n.missingEvidence.join(', '))}</small></div>`).join('')}</div>`:''}
    </section>
    <section class="card"><div class="split"><div><h3>Mốc thực hiện</h3><p class="note">Theo dõi công việc nghiên cứu, không chỉ trạng thái hành chính.</p></div><button class="btn sm" id="newMilestone">+ Mốc</button></div><div id="milestonesBox">${milestoneRows(ws.milestones||[])}</div></section>
    <section class="card"><div class="split"><div><h3>Nguồn học thuật đã đăng ký</h3><p class="note">Literature/Citation Intelligence chỉ được phép dựa trên nguồn thật đã nhập hoặc nội dung người dùng cung cấp.</p></div><button class="btn sm" id="newSource">+ Nguồn</button></div><div id="sourcesBox">${sourceRows(ws.sources||[])}</div></section>
    <section class="card"><div class="split"><div><h3>Nhật ký nghiên cứu</h3><p class="note">Ghi giả thuyết, quyết định phương pháp, quan sát và lý do thay đổi để hình thành institutional memory.</p></div><button class="btn sm" id="newNote">+ Ghi chú</button></div><div id="notesBox">${noteRows(ws.notes||[])}</div></section>
  </main>
  <aside class="workspace-ai-panel"><div class="ai-panel-head"><span class="workspace-ai-orb small">AI</span><div><h3>AI Research Partner</h3><p>AI hỗ trợ tư duy; không bịa nguồn, dữ liệu hay quyết định khoa học thay con người.</p></div></div>
    <div class="field"><span>Năng lực học thuật</span><select id="academicCap">${caps.map(c=>`<option value="${esc(c.code)}">${esc(c.label)}</option>`).join('')}</select></div>
    <div id="capPurpose" class="cap-purpose"></div>
    <div class="field"><span>Nhiệm vụ / câu hỏi</span><input id="academicTask" placeholder="Ví dụ: phản biện sự phù hợp giữa câu hỏi và phương pháp"></div>
    <div class="field"><span>Nội dung cần phân tích</span><textarea id="academicContent" style="min-height:180px" placeholder="Dán nội dung hoặc tải tệp bên dưới..."></textarea></div><div class="field"><span>Tệp bổ sung cho lần phân tích này</span><input id="academicFiles" type="file" multiple accept=".pdf,.doc,.docx,.txt,.md,.rtf"><div id="academicFilesList" class="file-stack"></div></div>
    <button class="btn primary full" id="runAcademic">Phân tích trong ngữ cảnh hồ sơ →</button><div id="academicResult" class="academic-result"></div>
    <div class="ai-history"><b>Phân tích gần đây</b>${(ws.analyses||[]).slice(0,5).map(a=>`<div><span>${esc((caps.find(c=>c.code===a.capability)||{}).label||a.capability)}</span><small>${fmt(a.createdAt)}</small></div>`).join('')||'<p class="note">Chưa có phân tích.</p>'}</div>
  </aside></div>`;
  $('#backWorkspace').onclick=()=>researchWorkspaceList();
  const capMap=Object.fromEntries(caps.map(c=>[c.code,c])); const updateCap=()=>{const c=capMap[$('#academicCap').value];$('#capPurpose').innerHTML=c?`<b>${esc(c.purpose)}</b><small>${(c.guardrails||[]).map(x=>esc(x)).join(' · ')}</small>`:''}; $('#academicCap').onchange=updateCap; updateCap();
  const academicPicker=setupMultiFileInput('#academicFiles','#academicFilesList');
  $('#runAcademic').onclick=async()=>{const box=$('#academicResult');box.className='academic-result loading';box.textContent='AI đang phân tích trong ngữ cảnh hồ sơ, nguồn và tri thức thể chế...';try{const r=await api(`/api/research/${id}/academic/analyze`,{method:'POST',body:JSON.stringify({capability:$('#academicCap').value,task:$('#academicTask').value,content:$('#academicContent').value,files:await filesPayload(academicPicker.files())})});box.className='academic-result';box.textContent=r.result}catch(e){box.className='academic-result error';box.textContent=e.message}};
  $('#newSource').onclick=()=>sourceModal(id); $('#newNote').onclick=()=>noteModal(id); $('#newMilestone').onclick=()=>milestoneModal(id);
  document.querySelectorAll('[data-ms-status]').forEach(b=>b.onclick=async()=>{try{await api(`/api/milestones/${b.dataset.msStatus}/status`,{method:'POST',body:JSON.stringify({status:b.dataset.to})});openResearchWorkspace(id)}catch(e){showError(e)}});
}
function milestoneRows(list){if(!list.length)return '<div class="empty slim">Chưa có mốc công việc.</div>';return `<div class="mini-list">${list.map(m=>`<div class="mini-row"><div><b>${esc(m.title)}</b><small>${m.dueDate?'Hạn '+esc(m.dueDate):'Chưa đặt hạn'} · ${esc(m.status)}</small></div>${m.status!=='DONE'?`<button class="btn sm" data-ms-status="${esc(m.id)}" data-to="DONE">Hoàn thành</button>`:'<span class="pill ok">Đã xong</span>'}</div>`).join('')}</div>`}
function sourceRows(list){if(!list.length)return '<div class="empty slim">Chưa đăng ký nguồn. AI không được tự bịa citation để bù khoảng trống này.</div>';return `<div class="mini-list">${list.map(s=>`<div class="mini-row"><div><b>${esc(s.title)}</b><small>${esc(s.authors||'')} ${s.year?'· '+esc(s.year):''} ${s.doi?'· DOI '+esc(s.doi):''}</small></div><span class="pill ${s.verified?'ok':''}">${s.verified?'Đã xác minh':'Chưa xác minh'}</span></div>`).join('')}</div>`}
function noteRows(list){if(!list.length)return '<div class="empty slim">Chưa có ghi chú nghiên cứu.</div>';return `<div class="mini-list">${list.slice(0,12).map(n=>`<div class="note-item"><b>${esc(n.title)}</b><p>${esc(n.content)}</p><small>${fmt(n.createdAt)}</small></div>`).join('')}</div>`}
function sourceModal(id){modal(`<h3>Đăng ký nguồn học thuật</h3><form id="sourceF"><div class="field"><span>Tên tài liệu</span><input name="title" required></div><div class="row"><div class="field"><span>Tác giả</span><input name="authors"></div><div class="field"><span>Năm</span><input name="year"></div></div><div class="row"><div class="field"><span>DOI</span><input name="doi"></div><div class="field"><span>URL</span><input name="url"></div></div><div class="field"><span>Ghi chú / nội dung liên quan</span><textarea name="notes"></textarea></div><label class="default-provider"><input type="checkbox" name="verified"><span><b>Đã xác minh metadata/nguồn</b><small>Chỉ bật khi người dùng đã kiểm tra nguồn thật.</small></span></label><div class="actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn primary">Lưu nguồn</button></div></form>`);$('#sourceF').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));f.verified=e.target.elements.verified.checked;try{await api(`/api/research/${id}/sources`,{method:'POST',body:JSON.stringify(f)});closeModal();openResearchWorkspace(id)}catch(x){showError(x)}}}
function noteModal(id){modal(`<h3>Ghi chú nghiên cứu</h3><form id="noteF"><div class="field"><span>Tiêu đề</span><input name="title" value="Ghi chú nghiên cứu"></div><div class="field"><span>Nội dung</span><textarea name="content" style="min-height:220px" required></textarea></div><div class="actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn primary">Lưu</button></div></form>`);$('#noteF').onsubmit=async e=>{e.preventDefault();try{await api(`/api/research/${id}/notes`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();openResearchWorkspace(id)}catch(x){showError(x)}}}
function milestoneModal(id){modal(`<h3>Thêm mốc thực hiện</h3><form id="msF"><div class="field"><span>Mốc / công việc</span><input name="title" required></div><div class="field"><span>Hạn hoàn thành</span><input name="dueDate" type="date"></div><div class="field"><span>Ghi chú</span><textarea name="note"></textarea></div><div class="actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn primary">Thêm mốc</button></div></form>`);$('#msF').onsubmit=async e=>{e.preventDefault();try{await api(`/api/research/${id}/milestones`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();openResearchWorkspace(id)}catch(x){showError(x)}}}

async function personnelPage(){const [people,orgs,roles]=await Promise.all([api('/api/personnel'),api('/api/organizations'),api('/api/roles')]);const catName={STAFF:'Cán bộ',LECTURER:'Giảng viên',STUDENT:'Sinh viên',RESEARCHER:'Nhà nghiên cứu',EXTERNAL:'Ngoài trường'};$('#view').innerHTML=`<div class="page-head"><div><h2>Danh sách cán bộ · giảng viên · sinh viên</h2><p>Danh mục con người theo đơn vị là nguồn cấp tài khoản và liên kết hồ sơ nghiên cứu.</p></div><button class="btn primary" id="newPerson">+ Thêm người</button></div><div class="card" style="margin-bottom:16px"><div class="row"><div class="field"><span>Lọc theo đơn vị</span><select id="personOrgFilter"><option value="">Tất cả đơn vị</option>${orgs.map(o=>`<option value="${esc(o.id)}">${esc(o.name)}</option>`).join('')}</select></div><div class="field"><span>Lọc theo nhóm</span><select id="personCatFilter"><option value="">Tất cả</option>${Object.entries(catName).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></div></div></div><div id="personnelTable"></div>`;const render=()=>{const org=$('#personOrgFilter').value,cat=$('#personCatFilter').value;const rows=people.filter(v=>(!org||v.organizationId===org)&&(!cat||v.category===cat));$('#personnelTable').innerHTML=`<div class="table-wrap"><table class="table"><thead><tr><th>Mã</th><th>Họ tên</th><th>Nhóm</th><th>Đơn vị</th><th>Email</th><th>Tài khoản</th><th></th></tr></thead><tbody>${rows.map(v=>`<tr><td>${esc(v.code||'')}</td><td><b>${esc(v.fullName)}</b></td><td>${esc(catName[v.category]||v.category)}</td><td>${esc(v.organization?.name||'')}</td><td>${esc(v.email||'')}</td><td>${v.user?`<span class="pill ok">${esc(v.user.username)}</span>`:'Chưa cấp'}</td><td>${v.user?`${(has('scientific.profile.approve')||has('user.manage'))?`<button class="btn sm" data-export-sci="${esc(v.user.id)}">Xuất LLKH</button>`:''}`:`<button class="btn sm" data-account="${esc(v.id)}">Cấp tài khoản</button>`}</td></tr>`).join('')||'<tr><td colspan="7" class="muted">Không có dữ liệu phù hợp.</td></tr>'}</tbody></table></div>`;document.querySelectorAll('[data-account]').forEach(b=>b.onclick=()=>personnelAccountModal(people.find(v=>v.id===b.dataset.account),roles));document.querySelectorAll('[data-export-sci]').forEach(b=>b.onclick=()=>window.demoExportScientificProfile(b.dataset.exportSci))};$('#personOrgFilter').onchange=render;$('#personCatFilter').onchange=render;render();$('#newPerson').onclick=()=>personnelModal(orgs)}

function personnelModal(orgs){modal(`<h3>Thêm cán bộ / giảng viên / sinh viên</h3><form id="pf"><div class="row"><div class="field"><span>Mã cán bộ / MSSV</span><input name="code"></div><div class="field"><span>Họ tên</span><input name="fullName" required></div></div><div class="row"><div class="field"><span>Nhóm</span><select name="category"><option value="LECTURER">Giảng viên</option><option value="STAFF">Cán bộ</option><option value="STUDENT">Sinh viên</option><option value="RESEARCHER">Nhà nghiên cứu</option><option value="EXTERNAL">Ngoài trường</option></select></div><div class="field"><span>Đơn vị</span><select name="organizationId" required><option value="">-- Chọn --</option>${orgs.filter(o=>o.active!==false).map(o=>`<option value="${esc(o.id)}">${esc(o.name)}</option>`).join('')}</select></div></div><div class="row"><div class="field"><span>Email</span><input name="email" type="email"></div><div class="field"><span>Chức danh / lớp</span><input name="title"></div></div><div class="actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn primary">Lưu</button></div></form>`);$('#pf').onsubmit=async e=>{e.preventDefault();try{await api('/api/personnel',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();personnelPage()}catch(x){showError(x)}}}
function personnelAccountModal(person,roles){modal(`<h3>Cấp tài khoản: ${esc(person.fullName)}</h3><form id="paf"><div class="field"><span>Tên đăng nhập</span><input name="username" value="${esc((person.email||person.code||'').split('@')[0])}" required></div><div class="field"><span>Mật khẩu khởi tạo</span><input name="password" type="password" minlength="10" required></div><div class="field"><span>Vai trò</span><select name="role" required><option value="">-- Chọn --</option>${roles.map(r=>`<option value="${esc(r.code)}">${esc(r.name)}</option>`).join('')}</select></div><div class="actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn primary">Cấp tài khoản</button></div></form>`);$('#paf').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));try{await api(`/api/personnel/${person.id}/account`,{method:'POST',body:JSON.stringify({username:f.username,password:f.password,roles:f.role?[f.role]:[]})});closeModal();personnelPage()}catch(x){showError(x)}}}
async function scientificProfilePage(){const p=await api('/api/scientific-profile/me');const snap=p.systemSnapshot||{};const ident=snap.identity||{};$('#view').innerHTML=`<div class="page-head"><div><h2>Hồ sơ khoa học</h2><p>Hồ sơ khoa học hợp nhất dữ liệu người dùng, đơn vị, hồ sơ năng lực, hoạt động nghiên cứu, minh chứng và tệp khoa học trong RIS.</p></div><div class="actions"><button class="btn" id="exportScientific">Xuất Lý lịch khoa học</button><button class="btn" id="syncScientific">↻ Đồng bộ dữ liệu RIS</button></div></div><div class="card" style="margin-bottom:18px"><div class="split"><div><h3>Liên kết định danh RIS</h3><p class="note">${esc(ident.displayName||p.user?.displayName||'')} · ${esc(ident.organizationName||p.organization?.name||'Chưa gán đơn vị')} ${ident.personnelCode?`· Mã: ${esc(ident.personnelCode)}`:''} ${ident.positionTitle?`· ${esc(ident.positionTitle)}`:''}</p></div><div class="note">${p.lastSyncedAt?`Đồng bộ gần nhất: ${fmt(p.lastSyncedAt)}`:'Dữ liệu tổng hợp bên phải được tính trực tiếp từ RIS; bấm Đồng bộ để ghi snapshot và bổ sung các trường còn trống.'}</div></div></div><div class="grid"><div class="card"><h3>Thông tin nhà nghiên cứu</h3><form id="sciForm"><div class="row"><div class="field"><span>Học hàm</span><input name="academicTitle" value="${esc(p.academicTitle||'')}"></div><div class="field"><span>Học vị</span><input name="degree" value="${esc(p.degree||'')}"></div></div><div class="row"><div class="field"><span>ORCID</span><input name="orcid" value="${esc(p.orcid||ident.orcid||'')}"></div><div class="field"><span>Scopus ID</span><input name="scopusId" value="${esc(p.scopusId||'')}"></div></div><div class="row"><div class="field"><span>WoS Researcher ID</span><input name="wosId" value="${esc(p.wosId||'')}"></div><div class="field"><span>Google Scholar</span><input name="googleScholarUrl" value="${esc(p.googleScholarUrl||'')}"></div></div><div class="field"><span>Lĩnh vực chuyên môn</span><input name="expertise" value="${esc((p.expertise?.length?p.expertise:ident.expertise||[]).join(', '))}"></div><div class="field"><span>Từ khóa</span><input name="keywords" value="${esc((p.keywords?.length?p.keywords:ident.keywords||[]).join(', '))}"></div><div class="field"><span>Tiểu sử khoa học</span><textarea name="bio">${esc(p.bio||'')}</textarea></div><div class="actions"><button class="btn primary">Lưu hồ sơ khoa học</button></div></form></div><div class="card"><h3>Dữ liệu tự đồng bộ từ RIS</h3><div class="cards grid"><div class="metric"><div class="label">Hoạt động tham gia</div><div class="num">${snap.researchCount||0}</div></div><div class="metric"><div class="label">Đã công nhận</div><div class="num">${snap.recognizedCount||0}</div></div><div class="metric"><div class="label">Công bố</div><div class="num">${snap.publicationCount||0}</div></div><div class="metric"><div class="label">SHTT</div><div class="num">${snap.intellectualPropertyCount||0}</div></div><div class="metric"><div class="label">Minh chứng</div><div class="num">${snap.evidenceCount||0}</div></div><div class="metric"><div class="label">Hội đồng</div><div class="num">${snap.councilCount||0}</div></div></div><div class="mini-list">${(snap.research||[]).slice(0,15).map(r=>`<div class="mini-row"><div><b>${esc(r.title)}</b><small>${esc(r.type)} · ${esc(r.status)}${r.organization?` · ${esc(r.organization)}`:''}</small></div></div>`).join('')||'<div class="empty">Chưa có hoạt động nghiên cứu liên kết với tài khoản này. Hãy kiểm tra chủ nhiệm/thành viên của hồ sơ nghiên cứu và tài khoản nhân sự.</div>'}</div></div></div><div class="card" style="margin-top:18px"><div class="split"><div><h3>Tệp hồ sơ khoa học</h3><p class="note">CV khoa học, bằng cấp, chứng nhận, danh mục công bố, quyết định, hồ sơ SHTT...</p></div><button class="btn sm" id="addSciDocs">+ Tải tệp</button></div><div class="file-stack">${(p.documents||[]).map(d=>`<span class="file-chip"><a href="${esc(d.fileUrl)}">${esc(d.originalName)} · ${esc(d.analysisReady&&!d.hasExtractedText?'AI_NATIVE_READY':d.extractionStatus||'STORED')}</a><button type="button" data-del-scidoc="${esc(d.id)}">×</button></span>`).join('')||'<span class="note">Chưa có tệp.</span>'}</div></div>`;$('#sciForm').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));f.expertise=f.expertise.split(',').map(x=>x.trim()).filter(Boolean);f.keywords=f.keywords.split(',').map(x=>x.trim()).filter(Boolean);try{await api('/api/scientific-profile/me',{method:'POST',body:JSON.stringify(f)});scientificProfilePage()}catch(x){showError(x)}};$('#syncScientific').onclick=async()=>{const b=$('#syncScientific');try{b.disabled=true;b.textContent='Đang đồng bộ...';await api('/api/scientific-profile/me/sync',{method:'POST',body:'{}'});await scientificProfilePage()}catch(e){showError(e)}finally{if(document.body.contains(b)){b.disabled=false;b.textContent='↻ Đồng bộ dữ liệu RIS'}}};if($('#exportScientific'))$('#exportScientific').onclick=()=>window.demoExportScientificProfile('me');$('#addSciDocs').onclick=()=>scientificDocsModal();document.querySelectorAll('[data-del-scidoc]').forEach(b=>b.onclick=async()=>{if(!confirm('Xóa tệp hồ sơ khoa học này?'))return;try{await api(`/api/scientific-profile/me/documents/${b.dataset.delScidoc}`,{method:'DELETE'});scientificProfilePage()}catch(e){showError(e)}})}
function scientificDocsModal(){modal(`<h3>Tải tệp hồ sơ khoa học</h3><form id="sdf"><div class="field"><span>Nhóm tài liệu</span><select name="category"><option>CV</option><option>DEGREE</option><option>CERTIFICATE</option><option>PUBLICATION_LIST</option><option>DECISION</option><option>IP</option><option>OTHER</option></select></div><div class="field"><span>Chọn nhiều tệp</span><input id="sciFiles" type="file" multiple accept=".pdf,.doc,.docx,.txt,.md,.rtf"><div id="sciFilesList" class="file-stack"></div></div><div class="actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn primary">Tải lên</button></div></form>`);const picker=setupMultiFileInput('#sciFiles','#sciFilesList');$('#sdf').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));try{f.files=await filesPayload(picker.files());await api('/api/scientific-profile/me/documents',{method:'POST',body:JSON.stringify(f)});closeModal();scientificProfilePage()}catch(x){showError(x)}}}

async function auditView(){const list=await api('/api/audit');$('#view').innerHTML=`<div class="page-head"><div><h2>Nhật ký hệ thống</h2><p>Dấu vết thao tác nghiệp vụ và AI.</p></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Thời gian</th><th>Actor</th><th>Hành động</th><th>Đối tượng</th><th>Chi tiết</th></tr></thead><tbody>${list.map(a=>`<tr><td>${fmt(a.at)}</td><td class="code">${esc(a.actorId)}</td><td>${esc(a.action)}</td><td>${esc(a.entityType)} / ${esc(a.entityId)}</td><td class="code">${esc(JSON.stringify(a.details||{})).slice(0,180)}</td></tr>`).join('')}</tbody></table></div>`}
function modal(html){const d=document.createElement('div');d.className='modal-bg';d.id='modal';d.innerHTML=`<div class="modal">${html}</div>`;document.body.append(d);d.onclick=e=>{if(e.target===d||e.target.matches('[data-close]'))closeModal()}}
function closeModal(){$('#modal')?.remove()}
function formObj(form){const f=Object.fromEntries(new FormData(form));f.active=form.elements.active?.checked||false;return f}
function fmt(d){if(!d)return '—';try{return new Intl.DateTimeFormat('vi-VN',{dateStyle:'short',timeStyle:'short'}).format(new Date(d))}catch{return d}}

function approvalLevelForRoles(roles,instance){const done=(instance.signatures||[]).map(x=>Number(x.approvalLevel)).filter(Boolean);const required=instance.template?.signaturePolicy?.requiredApprovalLevels||[2,3,4];const next=required.find(x=>!done.includes(x));if((roles||[]).includes('SYSTEM_ADMIN'))return next||4;if((roles||[]).includes('APPROVER_LEVEL_2'))return 2;if((roles||[]).includes('APPROVER_LEVEL_3'))return 3;if((roles||[]).includes('APPROVER_LEVEL_4'))return 4;return null}
async function createDigitalSignature(instance){if(!window.NuteDigitalSignature)throw new Error('Digital Signature Capability chưa được nạp.');return window.NuteDigitalSignature.signInstance(instance,{userId:state.me.id,roles:state.me.roles||[],approvalLevel:approvalLevelForRoles(state.me.roles||[],instance)})}
async function verifyDigitalSignature(instance,sig){if(!window.NuteDigitalSignature)return {ok:false,status:'CAPABILITY_NOT_LOADED'};return window.NuteDigitalSignature.verifyInstance(instance,sig)}
function downloadBlob(name,content,type='text/plain;charset=utf-8'){const b=new Blob([content],{type});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;document.body.append(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},300)}
function formDocHtml(tpl,inst){const val=inst.values||{};const sigs=inst.signatures||[];return `<!doctype html><html><head><meta charset="utf-8"><title>${esc(tpl.name)}</title><style>body{font-family:Arial,sans-serif;max-width:900px;margin:32px auto;color:#111;line-height:1.45}h1{text-align:center;font-size:22px}table{width:100%;border-collapse:collapse;margin-top:18px}td,th{border:1px solid #777;padding:9px;vertical-align:top}.label{width:28%;font-weight:700}.sig{margin-top:18px;border:1px solid #777;padding:14px}.small{font-size:12px;color:#555}@media print{.no-print{display:none}}</style></head><body><button class="no-print" onclick="print()">In / Lưu PDF</button><h1>${esc(tpl.name)}</h1><p style="text-align:center">Mã: ${esc(tpl.code)} · Phiên bản mẫu ${esc(tpl.version)} · Phiên bản dữ liệu ${esc(inst.documentVersion||1)}</p><table>${(tpl.fields||[]).map(f=>`<tr><td class="label">${esc(f.label)}${f.required?' *':''}</td><td>${esc(val[f.code]||'')}</td></tr>`).join('')}</table>${(tpl.legalBasis||[]).length?`<h3>Căn cứ</h3><ul>${tpl.legalBasis.map(x=>`<li>${esc(x.title||'')} — ${esc(x.citation||'')}</li>`).join('')}</ul>`:''}<h3>Chữ ký số kiểm duyệt</h3>${sigs.length?sigs.map(x=>`<div class="sig"><b>Cấp ${esc(x.approvalLevel||'?')} · ${esc(x.signerName||x.signerId)}</b><br>Thời gian: ${esc(x.signedAt)}<br>Adapter: ${esc(x.adapterId||'legacy')} · ${esc(x.providerType||'')}<br>Thuật toán: ${esc(x.algorithm||'')}<br>Trạng thái: ${esc(x.verificationStatus||'CHƯA XÁC MINH NGOÀI')}<br>${x.certificate?.serialNumber?`Chứng thư: ${esc(x.certificate.serialNumber)} · ${esc(x.certificate.issuer||'')}<br>`:''}<span class="small">SHA-256: ${esc(x.payloadHash||'')}</span></div>`).join(''):'<p>Chưa ký số.</p>'}<p class="small">Xuất từ NUTE RIS V7.0. Adapter WebCrypto chỉ dùng kiểm thử. Adapter Government Specialized CA yêu cầu Signature Bridge/PKI service để truy cập USB Token/remote signing, kiểm tra certificate chain và OCSP/CRL.</p></body></html>`}
function defaultFields(){return [{id:'f-'+Date.now()+'-1',code:'TITLE',label:'Tên/tiêu đề',type:'text',required:true,citation:'Cần đối chiếu quy chế'},{id:'f-'+Date.now()+'-2',code:'CONTENT',label:'Nội dung / thuyết minh',type:'textarea',required:true,citation:'Cần đối chiếu quy chế'},{id:'f-'+Date.now()+'-3',code:'EVIDENCE',label:'Minh chứng / tài liệu kèm theo',type:'textarea',required:false,citation:'Cần đối chiếu quy chế'}]}
async function formStudioPage(){const [ks,tpls]=await Promise.all([api('/api/knowledge'),api('/api/form-templates')]);$('#view').innerHTML=`<div class="page-head"><div><h2>AI Form Studio</h2><p>AI đọc quy chế đang hiệu lực, đề xuất Form Specification, con người kiểm tra rồi công bố. Không tự sửa mẫu production.</p></div><button class="btn primary" id="newFormAI">+ AI tạo mẫu</button></div><div class="card"><div class="kicker">QUY TẮC</div><p class="note">Mỗi trường nên có căn cứ; trường không xác định được căn cứ phải đánh dấu cần kiểm tra. Mẫu được version hóa và có chính sách ký số.</p></div><div class="grid" style="margin-top:18px">${tpls.map(t=>`<div class="card"><div class="split"><span class="pill">${esc(t.status)}</span><small>v${esc(t.version)}</small></div><h3>${esc(t.name)}</h3><p class="note">${(t.fields||[]).length} trường · ${(t.knowledgeIds||[]).length} nguồn quy chế · Ký số: ${t.signaturePolicy?.required?'Bắt buộc':'Không bắt buộc'}</p><div class="actions"><button class="btn sm" data-edit-form="${esc(t.id)}">Sửa specification</button><button class="btn primary sm" data-use-form="${esc(t.id)}">Nhập dữ liệu</button></div></div>`).join('')||'<div class="empty">Chưa có mẫu.</div>'}</div>`;$('#newFormAI').onclick=()=>formGenerateModal(ks);document.querySelectorAll('[data-edit-form]').forEach(b=>b.onclick=()=>formTemplateEditModal(tpls.find(t=>t.id===b.dataset.editForm)));document.querySelectorAll('[data-use-form]').forEach(b=>b.onclick=()=>newFormInstance(b.dataset.useForm))}
function parseAIFormResult(text,name,knowledgeIds,legalBasis){let obj=null;const m=String(text||'').match(/\{[\s\S]*\}/);if(m)try{obj=JSON.parse(m[0])}catch{};const fields=Array.isArray(obj?.fields)&&obj.fields.length?obj.fields.map((f,i)=>({id:f.id||`f-${Date.now()}-${i}`,code:String(f.code||`FIELD_${i+1}`).toUpperCase().replace(/[^A-Z0-9_]/g,'_'),label:String(f.label||f.name||`Trường ${i+1}`),type:['text','textarea','date','number','select'].includes(f.type)?f.type:'text',required:!!f.required,citation:String(f.citation||'NEEDS_REVIEW')})):defaultFields();return {code:String(obj?.code||name||'AI_FORM').toUpperCase().replace(/[^A-Z0-9]+/g,'_').slice(0,60),name:String(obj?.name||name||'Biểu mẫu do AI đề xuất'),version:'1.0.0',status:'DRAFT',knowledgeIds,legalBasis,fields,signaturePolicy:{required:true,minimumSignatures:3,requiredApprovalLevels:[2,3,4],allowedRoles:['APPROVER_LEVEL_2','APPROVER_LEVEL_3','APPROVER_LEVEL_4','SYSTEM_ADMIN']},generatedByAI:true}}
function formGenerateModal(ks){modal(`<h3>AI tạo mẫu từ quy chế</h3><form id="fgf"><div class="field"><span>Tên mẫu cần tạo</span><input name="name" required placeholder="Ví dụ: Phiếu đề nghị nghiệm thu đề tài"></div><div class="field"><span>Chọn quy chế làm căn cứ</span><div class="check-list">${ks.filter(k=>k.active!==false).map(k=>`<label><input type="checkbox" name="knowledge" value="${esc(k.id)}"> ${esc(k.title)}</label>`).join('')||'<span class="note">Kho tri thức đang trống.</span>'}</div></div><div class="field"><span>Yêu cầu bổ sung</span><textarea name="instruction" placeholder="Đối tượng áp dụng, loại hồ sơ, yêu cầu ký số..."></textarea></div><div class="actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn primary">AI phân tích & tạo bản nháp</button></div></form>`);$('#fgf').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const name=String(f.get('name')||'').trim();const ids=f.getAll('knowledge');if(!ids.length)return showError(new Error('Cần chọn ít nhất một quy chế.'));const selected=ks.filter(k=>ids.includes(k.id));const legalBasis=selected.map(k=>({knowledgeId:k.id,title:k.title,citation:'Nguồn quy chế được chọn - cần xác nhận điều/khoản'}));let proposal;try{if(aiBrowserEnabled()){const result=await realAIInfer({task:'Tạo Form Specification JSON chỉ từ quy chế được cung cấp. Không tự tạo quy định. JSON phải có name, code, fields; mỗi field có code,label,type,required,citation. Nếu không có căn cứ ghi NEEDS_REVIEW.',content:selected.map(k=>`### ${k.title}\n${k.content||k.contentPreview||''}`).join('\n\n')+'\n\nYêu cầu: '+String(f.get('instruction')||'')});proposal=parseAIFormResult(result.result,name,ids,legalBasis)}else proposal=parseAIFormResult('',name,ids,legalBasis);await api('/api/form-templates',{method:'POST',body:JSON.stringify(proposal)});closeModal();formStudioPage()}catch(x){showError(x)}}}
function formTemplateEditModal(t){modal(`<h3>Sửa Form Specification</h3><form id="fte"><div class="row"><div class="field"><span>Tên mẫu</span><input name="name" value="${esc(t.name)}" required></div><div class="field"><span>Phiên bản</span><input name="version" value="${esc(t.version)}" required></div></div><div class="field"><span>Trạng thái</span><select name="status"><option ${t.status==='DRAFT'?'selected':''}>DRAFT</option><option ${t.status==='PUBLISHED'?'selected':''}>PUBLISHED</option><option ${t.status==='RETIRED'?'selected':''}>RETIRED</option></select></div><div class="field"><span>Fields JSON</span><textarea name="fields" style="min-height:260px">${esc(JSON.stringify(t.fields||[],null,2))}</textarea></div><div class="actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn primary">Lưu specification</button></div></form>`);$('#fte').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));try{const fields=JSON.parse(f.fields);await api('/api/form-templates',{method:'POST',body:JSON.stringify({...t,name:f.name,version:f.version,status:f.status,fields})});closeModal();formStudioPage()}catch(x){showError(new Error('Fields JSON không hợp lệ: '+x.message))}}}
async function newFormInstance(templateId){const tpls=await api('/api/form-templates');const t=tpls.find(x=>x.id===templateId);if(!t)return;modal(`<h3>${esc(t.name)}</h3><form id="newInstance">${(t.fields||[]).map(f=>`<div class="field"><span>${esc(f.label)}${f.required?' *':''}</span>${f.type==='textarea'?`<textarea name="${esc(f.code)}" ${f.required?'required':''}></textarea>`:`<input type="${f.type==='date'?'date':f.type==='number'?'number':'text'}" name="${esc(f.code)}" ${f.required?'required':''}>`}<small class="field-help">Căn cứ: ${esc(f.citation||'NEEDS_REVIEW')}</small></div>`).join('')}<div class="actions"><button type="button" class="btn" data-close>Hủy</button><button class="btn primary">Lưu dữ liệu</button></div></form>`);$('#newInstance').onsubmit=async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));try{await api('/api/form-instances',{method:'POST',body:JSON.stringify({templateId:t.id,title:t.name,values,status:'DRAFT'})});closeModal();formsPage()}catch(x){showError(x)}}}
async function formsPage(){const rows=await api('/api/form-instances');$('#view').innerHTML=`<div class="page-head"><div><h2>Biểu mẫu điện tử</h2><p>Nhập dữ liệu → gửi kiểm duyệt → ký số → tải mẫu đã có dữ liệu để sử dụng.</p></div>${has('knowledge.manage')?'<button class="btn" id="toStudio">AI Form Studio</button>':''}</div>${rows.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Biểu mẫu</th><th>Người tạo</th><th>Trạng thái</th><th>Chữ ký</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.title)}</b><small>v${esc(r.templateVersion)}</small></td><td>${esc(r.createdByUser?.displayName||r.createdBy)}</td><td><span class="pill">${esc(r.status)}</span></td><td>${(r.signatures||[]).length}</td><td><button class="btn sm" data-open-instance="${esc(r.id)}">Mở</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Chưa có dữ liệu biểu mẫu. Vào AI Form Studio hoặc chọn một mẫu để nhập dữ liệu.</div>'}`;if($('#toStudio'))$('#toStudio').onclick=()=>go('form-studio');document.querySelectorAll('[data-open-instance]').forEach(b=>b.onclick=()=>formInstancePage(b.dataset.openInstance))}
async function formInstancePage(id){
  const inst=await api(`/api/form-instances/${id}`);const t=inst.template;const canSign=(state.me.roles||[]).some(r=>['APPROVER_LEVEL_2','APPROVER_LEVEL_3','APPROVER_LEVEL_4','SYSTEM_ADMIN'].includes(r));
  const sigChecks=await Promise.all((inst.signatures||[]).map(async s=>({s,result:await verifyDigitalSignature(inst,s)})));const level=approvalLevelForRoles(state.me.roles||[],inst);const required=t.signaturePolicy?.requiredApprovalLevels||[2,3,4];const done=(inst.signatures||[]).map(x=>Number(x.approvalLevel)).filter(Boolean);const next=required.find(x=>!done.includes(x));const maySign=canSign&&next&&Number(level)===Number(next)&&String(inst.status).startsWith('PENDING_LEVEL_');
  $('#view').innerHTML=`<div class="page-head"><div><button class="btn sm" id="backForms">← Biểu mẫu</button><h2 style="margin-top:12px">${esc(t.name)}</h2><p>Phiên bản ${esc(t.version)} · dữ liệu v${esc(inst.documentVersion||1)} · <span class="pill">${esc(inst.status)}</span></p></div><div class="actions"><button class="btn" id="downloadWord">Tải Word (.doc)</button><button class="btn" id="downloadHtml">Tải HTML</button><button class="btn" id="printPdf">In / Lưu PDF</button></div></div><div class="grid"><div class="card"><h3>Dữ liệu biểu mẫu</h3><form id="instanceForm">${(t.fields||[]).map(f=>`<div class="field"><span>${esc(f.label)}${f.required?' *':''}</span>${f.type==='textarea'?`<textarea name="${esc(f.code)}" ${f.required?'required':''}>${esc(inst.values?.[f.code]||'')}</textarea>`:`<input type="${f.type==='date'?'date':f.type==='number'?'number':'text'}" name="${esc(f.code)}" value="${esc(inst.values?.[f.code]||'')}" ${f.required?'required':''}>`}<small class="field-help">Căn cứ: ${esc(f.citation||'NEEDS_REVIEW')}</small></div>`).join('')}<div class="actions"><button class="btn" type="submit">Lưu dữ liệu</button>${inst.status==='DRAFT'?'<button class="btn primary" type="button" id="submitReview">Gửi kiểm duyệt</button>':''}</div></form></div><div class="card"><div class="split"><div><h3>Kiểm duyệt & ký số</h3><p class="note">Chuỗi ký bắt buộc: cấp 2 → cấp 3 → cấp 4. Chữ ký gắn với documentVersion; sửa dữ liệu sẽ tăng phiên bản và vô hiệu/xóa chữ ký cũ.</p></div><button class="btn sm" id="signatureProfile">Chứng thư của tôi</button></div><div class="approval-chain">${required.map(l=>`<span class="pill ${done.includes(l)?'ok':next===l?'warn':''}">${done.includes(l)?'✓ ':next===l?'→ ':''}Cấp ${l}</span>`).join(' ')}</div>${maySign?`<button class="btn primary" id="signInstance" style="margin-top:14px">Phê duyệt & ký số cấp ${next}</button>`:next?`<div class="note" style="margin-top:14px">Đang chờ chữ ký cấp ${next}. Tài khoản hiện tại ${level?`thuộc cấp ${level}`:'không có quyền ký'}.</div>`:'<div class="success" style="margin-top:14px">Đã đủ chữ ký theo chính sách biểu mẫu.</div>'}<div class="signature-list">${sigChecks.length?sigChecks.map(({s,result})=>`<div class="signature-card ${result.ok?'valid':'invalid'}"><b>Cấp ${esc(s.approvalLevel||'?')} · ${esc(s.signerName||s.signerId)}</b><span>${result.ok?'✓ Xác minh mật mã hợp lệ':s.providerType==='GOVERNMENT_SPECIALIZED_CA'?'◷ Cần xác minh PKI ngoài':'⚠ '+esc(result.status||'Không hợp lệ')}</span><small>${fmt(s.signedAt)} · ${esc(s.adapterId||'legacy')} · ${esc(s.algorithm||'')}</small>${s.certificate?.issuer?`<small>Issuer: ${esc(s.certificate.issuer)}</small>`:''}<small class="code">${esc(s.payloadHash||'')}</small></div>`).join(''):'<div class="empty">Chưa có chữ ký số.</div>'}</div></div></div>`;
  $('#backForms').onclick=()=>formsPage();$('#signatureProfile').onclick=()=>go('signature-settings');
  $('#instanceForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/form-instances',{method:'POST',body:JSON.stringify({id:inst.id,values:Object.fromEntries(new FormData(e.target)),status:inst.status})});formInstancePage(id)}catch(x){showError(x)}};
  if($('#submitReview'))$('#submitReview').onclick=async()=>{try{await api('/api/form-instances',{method:'POST',body:JSON.stringify({id:inst.id,values:Object.fromEntries(new FormData($('#instanceForm'))),status:'SUBMITTED'})});formInstancePage(id)}catch(x){showError(x)}};
  if($('#signInstance'))$('#signInstance').onclick=async()=>{try{const fresh=await api(`/api/form-instances/${id}`);const sig=await createDigitalSignature(fresh);await api(`/api/form-instances/${id}/signatures`,{method:'POST',body:JSON.stringify(sig)});formInstancePage(id)}catch(x){showError(x)}};
  const html=formDocHtml(t,inst);$('#downloadWord').onclick=()=>downloadBlob(`${t.code}-${inst.id}.doc`,html,'application/msword;charset=utf-8');$('#downloadHtml').onclick=()=>downloadBlob(`${t.code}-${inst.id}.html`,html,'text/html;charset=utf-8');$('#printPdf').onclick=()=>{const w=window.open('','_blank');if(!w)return;w.document.write(html);w.document.close();setTimeout(()=>w.print(),250)}
}

async function signatureSettingsPage(){
  const ds=window.NuteDigitalSignature;if(!ds){$('#view').innerHTML='<div class="error">Digital Signature Capability chưa được nạp.</div>';return}const profile=ds.getProfile(state.me.id);const cfg=ds.getConfig();const cert=profile?.certificate;
  $('#view').innerHTML=`<div class="page-head"><div><h2>Chữ ký & chứng thư số</h2><p>Capability độc lập <span class="code">digital.signature.*</span> với adapter WebCrypto test và Government Specialized CA.</p></div></div><div class="grid"><div class="card"><h3>Hồ sơ chữ ký của tôi</h3><div class="field"><span>Adapter sử dụng</span><select id="sigAdapter">${ds.adapterList().map(a=>`<option value="${esc(a.id)}" ${(profile?.adapterId||'browser_demo')===a.id?'selected':''}>${esc(a.name)}${a.production?' · production adapter':''}</option>`).join('')}</select></div><div class="note">Private key không được lưu trong RIS. Với chứng thư công vụ, RIS chỉ lưu metadata/chứng thư công khai; thao tác ký phải đi qua USB Token/remote signing thông qua Signature Bridge.</div><div class="field" style="margin-top:14px"><span>Đăng ký chứng thư công khai (.cer/.crt/.pem)</span><input id="certFile" type="file" accept=".cer,.crt,.pem,application/pkix-cert"></div><div id="certInfo">${cert?`<div class="signature-card valid"><b>${esc(cert.subject||'Chứng thư đã đăng ký')}</b><small>Issuer: ${esc(cert.issuer||'')}</small><small>Serial: ${esc(cert.serialNumber||'')}</small><small>Hiệu lực: ${esc(cert.validFrom||'')} → ${esc(cert.validTo||'')}</small><small>Loại nhận diện: ${esc(profile.certificateType||'')}</small><small class="code">SHA-256: ${esc(cert.fingerprintSha256||'')}</small></div>`:'<div class="empty">Chưa đăng ký chứng thư.</div>'}</div><div class="actions"><button class="btn primary" id="saveSigProfile">Lưu hồ sơ chữ ký</button>${profile?'<button class="btn" id="removeSigProfile">Xóa hồ sơ</button>':''}</div></div>${has('config.manage')?`<div class="card"><h3>Government Specialized CA Adapter</h3><p class="note">GitHub Pages không thể tự truy cập USB Token/CSP/PKCS#11. Adapter production gọi một Signature Bridge do Nhà trường triển khai ở môi trường tin cậy.</p><div class="field"><span>Signature Bridge URL</span><input id="bridgeUrl" value="${esc(cfg.bridgeUrl||'')}" placeholder="Ví dụ: https://signature-bridge.nute.edu.vn"></div><div class="field"><span>Mẫu nhận diện issuer, mỗi dòng một cụm từ</span><textarea id="issuerPatterns">${esc((cfg.governmentIssuerPatterns||['Ban Cơ yếu','Government Specialized','Chuyên dùng công vụ']).join('\n'))}</textarea></div><button class="btn primary" id="saveSigConfig">Lưu cấu hình adapter</button><div class="note" style="margin-top:12px">Bridge production phải thực hiện: certificate chain validation, thời hạn, key usage, OCSP/CRL, timestamp và ký bằng private key nằm ngoài RIS.</div></div>`:''}</div>`;
  let inspected=null;$('#certFile').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;try{inspected=await ds.inspectCertificate(f);const typ=ds.classifyCertificate(inspected);$('#certInfo').innerHTML=`<div class="signature-card ${inspected.parseError?'invalid':'valid'}"><b>${esc(inspected.subject||f.name)}</b><small>Issuer: ${esc(inspected.issuer||'Không đọc được')}</small><small>Serial: ${esc(inspected.serialNumber||'')}</small><small>Hiệu lực: ${esc(inspected.validFrom||'')} → ${esc(inspected.validTo||'')}</small><small>Nhận diện: ${esc(typ)}</small><small class="code">SHA-256: ${esc(inspected.fingerprintSha256)}</small>${inspected.parseError?`<small>Parse: ${esc(inspected.parseError)}</small>`:''}</div>`}catch(x){showError(x)}};
  $('#saveSigProfile').onclick=()=>{const adapterId=$('#sigAdapter').value;const old=ds.getProfile(state.me.id)||{};const certificate=inspected||old.certificate||null;const certificateType=certificate?ds.classifyCertificate(certificate):'NONE';ds.saveProfile(state.me.id,{...old,id:old.id||`sigprof-${state.me.id}`,userId:state.me.id,adapterId,certificate,certificateType,updatedAt:new Date().toISOString()});signatureSettingsPage()};
  if($('#removeSigProfile'))$('#removeSigProfile').onclick=()=>{if(confirm('Xóa hồ sơ chữ ký của tài khoản này?')){ds.removeProfile(state.me.id);signatureSettingsPage()}};
  if($('#saveSigConfig'))$('#saveSigConfig').onclick=()=>{ds.saveConfig({bridgeUrl:$('#bridgeUrl').value.trim(),governmentIssuerPatterns:$('#issuerPatterns').value.split(/\n+/).map(x=>x.trim()).filter(Boolean)});alert('Đã lưu cấu hình Digital Signature Adapter.');signatureSettingsPage()}
}


boot();
